window.BOOK={"samples": {"D3D7.Basic": {"era": "D3D7", "tier": null, "desc": "The 1999 baseline: DirectDraw 7 surfaces + a D3D7 device, steered entirely by render states and transforms. Windowed via a DirectDraw clipper and a manual back-buffer blit.", "lines": 165, "url": "sample-D3D7.Basic.html", "ok": true, "anim": true, "frames": 36, "ms": 4069, "lang": "C++"}, "D3D8.Basic": {"era": "D3D8", "tier": null, "desc": "DirectDraw is gone: one IDirect3D8 device, present parameters, vertex/index buffers. Uses vendored Wine headers because the modern SDK no longer ships d3d8.h.", "lines": 138, "url": "sample-D3D8.Basic.html", "ok": true, "anim": true, "frames": 36, "ms": 4047, "lang": "C++"}, "D3D9.Basic": {"era": "D3D9", "tier": null, "desc": "The IDirect3D9 fixed-function cube - the baseline the D3D9 shader samples build on.", "lines": 116, "url": "sample-D3D9.Basic.html", "ok": true, "anim": true, "frames": 36, "ms": 4038, "lang": "C++"}, "D3D9.PixelShader": {"era": "D3D9", "tier": null, "desc": "Pixel shader paints an animated procedural color.", "lines": 166, "url": "sample-D3D9.PixelShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4056, "lang": "C++"}, "D3D9.VertexShader": {"era": "D3D9", "tier": null, "desc": "Vertex shader breathes/deforms the cube.", "lines": 165, "url": "sample-D3D9.VertexShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4029, "lang": "C++"}, "D3D10.Basic": {"era": "D3D10", "tier": null, "desc": "The great redesign: device + DXGI swap chain, render-target views, constant buffers and HLSL compiled at runtime with D3DCompile. No fixed function left.", "lines": 162, "url": "sample-D3D10.Basic.html", "ok": true, "anim": true, "frames": 36, "ms": 4031, "lang": "C++"}, "D3D10.GeometryShader": {"era": "D3D10", "tier": null, "desc": "Geometry shader explodes triangles along face normals.", "lines": 183, "url": "sample-D3D10.GeometryShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4035, "lang": "C++"}, "D3D10.PixelShader": {"era": "D3D10", "tier": null, "desc": "Pixel shader procedural color.", "lines": 167, "url": "sample-D3D10.PixelShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4022, "lang": "C++"}, "D3D10.VertexShader": {"era": "D3D10", "tier": null, "desc": "Vertex shader twists the cube.", "lines": 167, "url": "sample-D3D10.VertexShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4017, "lang": "C++"}, "D3D11.Basic": {"era": "D3D11", "tier": null, "desc": "Device and immediate context split apart, feature levels, and the same HLSL pipeline as D3D10.", "lines": 165, "url": "sample-D3D11.Basic.html", "ok": true, "anim": true, "frames": 36, "ms": 4017, "lang": "C++"}, "D3D11.ComputeShader": {"era": "D3D11", "tier": null, "desc": "Compute shader writes an animated texture (UAV) the cube then samples.", "lines": 211, "url": "sample-D3D11.ComputeShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4040, "lang": "C++"}, "D3D11.GeometryShader": {"era": "D3D11", "tier": null, "desc": "Geometry shader exploding cube.", "lines": 176, "url": "sample-D3D11.GeometryShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4023, "lang": "C++"}, "D3D11.PixelShader": {"era": "D3D11", "tier": null, "desc": "Pixel shader procedural color.", "lines": 167, "url": "sample-D3D11.PixelShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4023, "lang": "C++"}, "D3D11.Tessellation": {"era": "D3D11", "tier": null, "desc": "Hull/domain shaders subdivide the cube and bulge it toward a sphere (wireframe).", "lines": 199, "url": "sample-D3D11.Tessellation.html", "ok": true, "anim": true, "frames": 36, "ms": 4026, "lang": "C++"}, "D3D11.VertexShader": {"era": "D3D11", "tier": null, "desc": "Vertex shader twist.", "lines": 168, "url": "sample-D3D11.VertexShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4016, "lang": "C++"}, "D3D12.Basic": {"era": "D3D12", "tier": "Tier1", "desc": "The minimal explicit cube: command queue, allocator, list, fence, PSO and a root signature with MVP passed as 32-bit root constants.", "lines": 295, "url": "sample-D3D12.Basic.html", "ok": true, "anim": true, "frames": 36, "ms": 4056, "lang": "C++"}, "D3D12.ConstantBuffers": {"era": "D3D12", "tier": "Tier1", "desc": "An UPLOAD constant buffer bound via a CBV descriptor table (vs. root constants), 256-byte CBV alignment, and per-frame CB regions to avoid overwriting data the GPU is still reading.", "lines": 614, "url": "sample-D3D12.ConstantBuffers.html", "ok": true, "anim": true, "frames": 36, "ms": 4071, "lang": "C"}, "D3D12.Fundamentals": {"era": "D3D12", "tier": "Tier1", "desc": "The core objects: device, command queue/allocator/list, swap chain, RTV/DSV descriptor heaps, resource barriers, the fence sync model, root signature, and PSO. Live panel shows the fence value (CPU vs GPU-completed), back-buffer index, and barrier count each frame. Controls: pause, speed, wireframe (second PSO), vsync, clear color.", "lines": 640, "url": "sample-D3D12.Fundamentals.html", "ok": true, "anim": true, "frames": 36, "ms": 4051, "lang": "C"}, "D3D12.Nuklear": {"era": "D3D12", "tier": "Tier1", "desc": "An immediate-mode GUI (Nuklear) rendered on a Direct3D 12 backend - the full widget overview that every annotated D3D12 sample builds its live panel on.", "lines": 395, "url": "sample-D3D12.Nuklear.html", "ok": true, "anim": true, "frames": 36, "ms": 4041, "lang": "C"}, "D3D12.PixelShader": {"era": "D3D12", "tier": "Tier1", "desc": "Pixel shader procedural color.", "lines": 289, "url": "sample-D3D12.PixelShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4005, "lang": "C++"}, "D3D12.RootSignatures": {"era": "D3D12", "tier": "Tier1", "desc": "The three root-parameter kinds side by side — root constants, root descriptors (CBV), and descriptor tables — plus how root-signature layout affects binding cost.", "lines": 627, "url": "sample-D3D12.RootSignatures.html", "ok": true, "anim": true, "frames": 36, "ms": 4051, "lang": "C"}, "D3D12.Textures": {"era": "D3D12", "tier": "Tier1", "desc": "The full texture-upload path: a DEFAULT-heap texture staged from an UPLOAD buffer via GetCopyableFootprints + CopyTextureRegion, the COPY_DEST -> PIXEL_SHADER_RESOURCE barrier, an SRV in a shader-visible heap bound through a root descriptor table, and static point (s0) / linear (s1) samplers.", "lines": 714, "url": "sample-D3D12.Textures.html", "ok": true, "anim": true, "frames": 36, "ms": 4051, "lang": "C"}, "D3D12.TripleBuffering": {"era": "D3D12", "tier": "Tier1", "desc": "Multiple frames in flight: N back buffers + per-frame command allocators + a fence value per frame, so the CPU stops blocking on every Present and instead only waits when it laps the GPU.", "lines": 624, "url": "sample-D3D12.TripleBuffering.html", "ok": true, "anim": true, "frames": 36, "ms": 4051, "lang": "C"}, "D3D12.VertexShader": {"era": "D3D12", "tier": "Tier1", "desc": "Vertex shader twist (root constants).", "lines": 288, "url": "sample-D3D12.VertexShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4018, "lang": "C++"}, "D3D12.CopyQueue": {"era": "D3D12", "tier": "Tier2", "desc": "A dedicated COPY queue uploading data in parallel with rendering, with a cross-queue fence so the graphics queue waits for the copy to finish.", "lines": 610, "url": "sample-D3D12.CopyQueue.html", "ok": true, "anim": true, "frames": 36, "ms": 4058, "lang": "C"}, "D3D12.GeometryShader": {"era": "D3D12", "tier": "Tier2", "desc": "Geometry shader exploding cube.", "lines": 298, "url": "sample-D3D12.GeometryShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4057, "lang": "C++"}, "D3D12.IndirectDraw": {"era": "D3D12", "tier": "Tier2", "desc": "ExecuteIndirect with a command signature: draw arguments sourced from a GPU buffer so the GPU drives draw counts/parameters without CPU round-trips.", "lines": 593, "url": "sample-D3D12.IndirectDraw.html", "ok": true, "anim": true, "frames": 36, "ms": 4062, "lang": "C"}, "D3D12.PlacedResources": {"era": "D3D12", "tier": "Tier2", "desc": "Explicit heaps + CreatePlacedResource: sub-allocating several resources from one heap, resource-heap tiers, and aliasing considerations.", "lines": 570, "url": "sample-D3D12.PlacedResources.html", "ok": true, "anim": true, "frames": 36, "ms": 4054, "lang": "C"}, "D3D12.Tessellation": {"era": "D3D12", "tier": "Tier2", "desc": "Tessellation PSO subdivides + bulges the cube (wireframe).", "lines": 314, "url": "sample-D3D12.Tessellation.html", "ok": true, "anim": true, "frames": 36, "ms": 4023, "lang": "C++"}, "D3D12.Bindless": {"era": "D3D12", "tier": "Tier3", "desc": "SM5.1 dynamic indexing: an unbounded descriptor-table range (Texture2D g_tex[]) with a per-draw root-constant index selecting one of many textures — no re-binding between draws.", "lines": 673, "url": "sample-D3D12.Bindless.html", "ok": true, "anim": true, "frames": 36, "ms": 4048, "lang": "C"}, "D3D12.ComputeAsync": {"era": "D3D12", "tier": "Tier3", "desc": "An async COMPUTE queue running a compute shader (RWStructuredBuffer via a root UAV) that animates the cube vertices; the graphics queue Wait()s on the compute fence before drawing.", "lines": 647, "url": "sample-D3D12.ComputeAsync.html", "ok": true, "anim": true, "frames": 36, "ms": 4052, "lang": "C"}, "D3D12.ComputeShader": {"era": "D3D12", "tier": "Tier3", "desc": "Compute PSO writes a UAV texture, graphics PSO samples it via a descriptor table.", "lines": 380, "url": "sample-D3D12.ComputeShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4021, "lang": "C++"}, "D3D12.DeferredMRT": {"era": "D3D12", "tier": "Tier3", "desc": "A G-buffer with Multiple Render Targets (albedo + normal in one pass), then a fullscreen-triangle lighting pass that samples them. Combo view of lit/albedo/normal.", "lines": 732, "url": "sample-D3D12.DeferredMRT.html", "ok": true, "anim": true, "frames": 36, "ms": 4065, "lang": "C"}, "D3D12.AmplificationShader": {"era": "D3D12", "tier": "Tier4", "desc": "Amplification shader turns one dispatch into a ring of orbiting cubes, each emitted by a mesh group.", "lines": 356, "url": "sample-D3D12.AmplificationShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4030, "lang": "C++"}, "D3D12.MSAA": {"era": "D3D12", "tier": "Tier4", "desc": "A multisampled render target (2x/4x/8x, capability-gated via CheckFeatureSupport) resolved into the back buffer with ResolveSubresource. Live sample-count selector.", "lines": 681, "url": "sample-D3D12.MSAA.html", "ok": true, "anim": true, "frames": 36, "ms": 4065, "lang": "C"}, "D3D12.MeshShader": {"era": "D3D12", "tier": "Tier4", "desc": "Mesh shader generates the whole cube on the GPU — no vertex/index buffers or input assembler.", "lines": 342, "url": "sample-D3D12.MeshShader.html", "ok": true, "anim": true, "frames": 36, "ms": 4029, "lang": "C++"}, "D3D12.RayTracing": {"era": "D3D12", "tier": "Tier4", "desc": "Full DXR pipeline: a BLAS/TLAS cube ray-traced per pixel; the TLAS instance is rotated each frame.", "lines": 520, "url": "sample-D3D12.RayTracing.html", "ok": true, "anim": true, "frames": 36, "ms": 4011, "lang": "C++"}, "D3D12.ShadowMap": {"era": "D3D12", "tier": "Tier4", "desc": "Two-pass shadow mapping: render depth from the light's POV into an R32_TYPELESS shadow map (D32 DSV + R32 SRV), then sample it with a SamplerComparisonState / SampleCmpLevelZero. Depth-bias slider.", "lines": 791, "url": "sample-D3D12.ShadowMap.html", "ok": true, "anim": true, "frames": 36, "ms": 4053, "lang": "C"}, "D3D12.VariableRateShading": {"era": "D3D12", "tier": "Tier4", "desc": "Per-draw VRS (RSSetShadingRate on ID3D12GraphicsCommandList5), capability-gated on D3D12_FEATURE_D3D12_OPTIONS6. A fine procedural pattern makes coarse rates (2x2, 4x4) visibly blocky.", "lines": 582, "url": "sample-D3D12.VariableRateShading.html", "ok": true, "anim": true, "frames": 36, "ms": 4072, "lang": "C"}, "D3D12.Bundles": {"era": "D3D12", "tier": "Tier5", "desc": "A D3D12_COMMAND_LIST_TYPE_BUNDLE recorded once at init and replayed each frame with ExecuteBundle; the direct list sets the inherited root signature + root constants. Toggle between bundle replay and inline re-recording.", "lines": 677, "url": "sample-D3D12.Bundles.html", "ok": true, "anim": true, "frames": 36, "ms": 4052, "lang": "C"}, "D3D12.MultiThreadedRecording": {"era": "D3D12", "tier": "Tier5", "desc": "Parallel command-list recording: each worker thread records a slice of a cube grid into its own allocator + list, coordinated with Win32 events, then all lists are submitted in order with one ExecuteCommandLists. The concrete payoff of the queue/allocator/list split.", "lines": 776, "url": "sample-D3D12.MultiThreadedRecording.html", "ok": true, "anim": true, "frames": 36, "ms": 4049, "lang": "C"}, "D3D12.Predication": {"era": "D3D12", "tier": "Tier5", "desc": "Occlusion-query-driven predication: a BINARY_OCCLUSION query resolves into a predicate buffer, and SetPredication(..., EQUAL_ZERO) makes the GPU skip the expensive draw when fully occluded — no CPU round-trip.", "lines": 757, "url": "sample-D3D12.Predication.html", "ok": true, "anim": true, "frames": 36, "ms": 4063, "lang": "C"}, "D3D12.Queries": {"era": "D3D12", "tier": "Tier5", "desc": "Timestamp queries (GPU pass duration via GetTimestampFrequency) and pipeline-statistics queries (IA vertices, VS/PS invocations) resolved to a readback buffer and shown live.", "lines": 703, "url": "sample-D3D12.Queries.html", "ok": true, "anim": true, "frames": 36, "ms": 4063, "lang": "C"}, "D3D12.Blending": {"era": "D3D12", "tier": "Tier6", "desc": "Alpha vs. additive blend PSOs, back-to-front sorting (toggle to see sorting artifacts), and depth-write off for transparents. Shows why transparency order matters.", "lines": 658, "url": "sample-D3D12.Blending.html", "ok": true, "anim": true, "frames": 36, "ms": 4054, "lang": "C"}, "D3D12.Instancing": {"era": "D3D12", "tier": "Tier6", "desc": "DrawIndexedInstanced with a per-instance vertex slot (PER_INSTANCE_DATA, offset + tint), rendering a whole grid of cubes in a single draw call. Instance-count slider.", "lines": 622, "url": "sample-D3D12.Instancing.html", "ok": true, "anim": true, "frames": 36, "ms": 4043, "lang": "C"}, "D3D12.Stencil": {"era": "D3D12", "tier": "Tier6", "desc": "A two-pass stencil mask (D24_UNORM_S8_UINT): pass 1 writes stencil in a mask shape, pass 2 draws the cube only where StencilFunc == EQUAL — the mirror/portal/decal building block.", "lines": 670, "url": "sample-D3D12.Stencil.html", "ok": true, "anim": true, "frames": 36, "ms": 4054, "lang": "C"}, "D3D12.HDR": {"era": "D3D12", "tier": "Tier7", "desc": "An HDR10 swap chain (R10G10B10A2 + ST2084 color space via IDXGISwapChain3::SetColorSpace1), CheckColorSpaceSupport negotiation, IDXGIOutput6 luminance query, and a paper-white/brightness control. Graceful SDR fallback.", "lines": 687, "url": "sample-D3D12.HDR.html", "ok": true, "anim": true, "frames": 36, "ms": 4049, "lang": "C"}, "D3D12.MultiAdapter": {"era": "D3D12", "tier": "Tier7", "desc": "Explicit adapter enumeration (IDXGIFactory6::EnumAdapterByGpuPreference with fallback), listing each adapter's VRAM/vendor/flags, and selecting the high-performance GPU to render on. Explains cross-adapter shared resources.", "lines": 669, "url": "sample-D3D12.MultiAdapter.html", "ok": true, "anim": true, "frames": 36, "ms": 4053, "lang": "C"}, "D3D12.Debugging": {"era": "D3D12", "tier": "Tier8", "desc": "The validation tooling that replaces the driver's safety net: debug layer, GPU-based validation, DRED, live ID3D12InfoQueue message drain, PIX markers (encoded by hand, no pix3.h), and a button that deliberately triggers a benign validation warning. A DirectX Dump Files (preview) panel explains console-style GPU crash dumps and probes D3D12_FEATURE_DUMP_FILE / ID3D12DevicePreview, reporting \"not available\" on the retail runtime (the API ships in Agility SDK 1.721-preview but isn't usable yet).", "lines": 933, "url": "sample-D3D12.Debugging.html", "ok": true, "anim": true, "frames": 36, "ms": 4051, "lang": "C"}, "D3D12.PipelineLibraries": {"era": "D3D12", "tier": "Tier8", "desc": "Caching compiled PSOs to disk with ID3D12PipelineLibrary (Load/Store + Serialize to a .cache file); logs cold-create vs cached-load timing so you can see the first-run-compiles-then-caches behavior.", "lines": 484, "url": "sample-D3D12.PipelineLibraries.html", "ok": true, "anim": true, "frames": 36, "ms": 4052, "lang": "C"}, "D3D12.ReservedResources": {"era": "D3D12", "tier": "Tier8", "desc": "Reserved (tiled/sparse) textures: CreateReservedResource + UpdateTileMappings binding virtual tiles to a small heap, capability-gated on TiledResourcesTier with a committed-resource fallback.", "lines": 815, "url": "sample-D3D12.ReservedResources.html", "ok": true, "anim": true, "frames": 36, "ms": 4060, "lang": "C"}, "D3D12.DirectStorage": {"era": "D3D12", "tier": "Tier9", "desc": "Fast asset streaming (2022): IDStorageFactory → queue → request → submit → fence, loading bytes straight from disk into a D3D12 resource. Uses the out-of-band Microsoft.Direct3D.DirectStorage NuGet SDK (vendored locally, git-ignored).", "lines": 779, "url": "sample-D3D12.DirectStorage.html", "ok": false, "anim": false, "frames": 12, "ms": 1320, "lang": "C++"}, "D3D12.DynamicResources": {"era": "D3D12", "tier": "Tier9", "desc": "Shader Model 6.6 dynamic resources / bindless: HEAP_DIRECTLY_INDEXED root flags let HLSL index ResourceDescriptorHeap[] / SamplerDescriptorHeap[] directly with no descriptor tables in the root signature. Gated on shader model + resource-binding tier.", "lines": 498, "url": "sample-D3D12.DynamicResources.html", "ok": true, "anim": true, "frames": 36, "ms": 4021, "lang": "C++"}, "D3D12.EnhancedBarriers": {"era": "D3D12", "tier": "Tier9", "desc": "The modern barrier model: ID3D12GraphicsCommandList7::Barrier with D3D12_TEXTURE_BARRIER groups splitting SYNC / ACCESS / LAYOUT for precise, less over-synchronizing transitions. Gated on EnhancedBarriersSupported, with a legacy ResourceBarrier fallback.", "lines": 440, "url": "sample-D3D12.EnhancedBarriers.html", "ok": true, "anim": true, "frames": 36, "ms": 4010, "lang": "C++"}, "D3D12.LinearAlgebra": {"era": "D3D12", "tier": "Tier9", "desc": "SM6.10 preview. GPU-accelerated matrix math for neural rendering (#include <dx/linalg.h>, cs_6_10): a thread-scope F16 matrix × SM6.9 long-vector Multiply (inference) plus VectorAccumulate (InterlockedAccumulate), which sums 256 threads' gradients atomically (training). Both results are checked against the CPU and charted on the cube's faces. Gated on D3D12_FEATURE_LINEAR_ALGEBRA_SUPPORT. Needs the preview Agility SDK (1.721.2-preview) + preview DXC + Developer Mode, all vendored by fetch-deps.ps1. Runs on hardware when the driver exposes LinAlg, otherwise on the vendored preview WARP (--hw / --warp override).", "lines": 981, "url": "sample-D3D12.LinearAlgebra.html", "ok": true, "anim": true, "frames": 36, "ms": 4024, "lang": "C++"}, "D3D12.PartialPrograms": {"era": "D3D12", "tier": "Tier9", "desc": "1.721 preview. Partial graphics programs: one VS and one PS compiled once as pre-rasterization and pixel-shader partials in a state-object collection, then late-linked (blend / rasterizer / depth) into five generic programs with AddToStateObject. It draws opaque, additive and alpha cubes with SetProgram; P swaps in equivalent classic PSOs, and the title compares compile, link and first-draw times. The basis for Advanced Shader Delivery. Needs D3D12StateObjectsExperiment; falls back to preview WARP, then to a classic PSO.", "lines": 1011, "url": "sample-D3D12.PartialPrograms.html", "ok": true, "anim": true, "frames": 36, "ms": 4029, "lang": "C++"}, "D3D12.RayTracing12": {"era": "D3D12", "tier": "Tier9", "desc": "DXR 1.2 / Shader Model 6.9. Opacity micromaps cut a different hole into each cube face: 12 OC1 4-state OMMs in an OMM array built with BuildRaytracingAccelerationStructure, linked to the BLAS triangles, pipeline flag ALLOW_OPACITY_MICROMAPS. O cycles OMM 2-state (0 any-hit calls) / OMM 4-state (~4K) / any-hit alpha test (~162K) / opaque. Shader Execution Reordering: dx::HitObject::TraceRay → dx::MaybeReorderThread(hit, faceHint, 3) → HitObject::Invoke, toggled with S, with the OPTIONS22.ShaderExecutionReorderingActuallyReorders cap and GPU timestamps in the title. Hardware → preview WARP → DXR 1.0 fallback.", "lines": 1187, "url": "sample-D3D12.RayTracing12.html", "ok": true, "anim": true, "frames": 36, "ms": 4072, "lang": "C++"}, "D3D12.SamplerFeedback": {"era": "D3D12", "tier": "Tier9", "desc": "DirectX 12 Ultimate Sampler Feedback: a paired feedback map (CreateSamplerFeedbackUnorderedAccessView, DXGI_FORMAT_SAMPLER_FEEDBACK_) records which* texture mips a shader actually sampled (via WriteSamplerFeedback in SM6.5) — the basis for texture streaming and texture-space shading. Gated on SamplerFeedbackTier.", "lines": 516, "url": "sample-D3D12.SamplerFeedback.html", "ok": false, "anim": false, "frames": 12, "ms": 1320, "lang": "C++"}, "D3D12.WorkGraphs": {"era": "D3D12", "tier": "Tier9", "desc": "GPU-driven Work Graphs (2024): an executable state object of shader nodes launched with DispatchGraph (ID3D12GraphicsCommandList10) so the GPU spawns its own follow-on work. Gated on WorkGraphsTier.", "lines": 604, "url": "sample-D3D12.WorkGraphs.html", "ok": true, "anim": true, "frames": 36, "ms": 4034, "lang": "C++"}}, "pages": ["part-00-orientation.html", "part-01-fixed-function-era.html", "part-02-programmable-shading.html", "part-03-great-redesign.html", "part-04-maturity-generality.html", "part-05-going-explicit-d3d12.html", "part-06-feeding-the-gpu.html", "part-07-image-quality-modern-pipeline.html", "part-08-recording-querying-at-scale.html", "part-09-classic-pipeline-mastery.html", "part-10-presentation-devices-resources.html", "part-11-the-frontier.html", "part-12-synthesis.html", "appendices.html"], "search": [{"t": "The Evolution of Direct3D", "p": "Welcome & syllabus", "u": "course.html#the-evolution-of-direct3d", "x": "#"}, {"t": "From Fixed-Function to GPU-Driven Rendering (D3D7 → D3D12)", "p": "Welcome & syllabus", "u": "course.html#from-fixed-function-to-gpu-driven-rendering-d3d7-d3d12", "x": "# A code-driven course, taught through the RotatingCubes sample set."}, {"t": "Welcome to the course", "p": "Welcome & syllabus", "u": "course.html#welcome-to-the-course", "x": "# This is a self-paced course on how Microsoft's Direct3D API evolved across two decades — from the fixed-function D3D7 of 1999 to the explicit, GPU-driven D3D12 of today. Rather than march through API reference pages, we learn by reading a family of small, complete programs that all do the exact same thing : spin a colored cube on the screen. That shared goal is the whole trick. Because the result never changes , the only thing that differs from one sample to the next is the API you must use to achieve it . The cube is a control variable in a controlled experiment. When D3D7 needs 160 lines and D3D12's fundamentals need 700, that difference isn't noise — it is the lesson. Every extra line D3D12 asks of you buys back some control the older runtimes were quietly exercising on your behalf."}, {"t": "What makes this course different", "p": "Welcome & syllabus", "u": "course.html#what-makes-this-course-different", "x": "# Most API tutorials answer \"how?\" This one insists on also answering \"when?\" and \"why?\" For every feature we study, we ask: The problem — what real need forced this into existence? How it works — the mechanics, with short excerpts from the sample. When to use it — the situations where it's the right tool. When not to use it — the costs, and when the older/simpler way wins. Trade-offs & decision guidance — the engineering judgment involved. Historical \"why now?\" — why it arrived in this era and not earlier. You'll also find recurring Decision lens callouts: short, opinionated frameworks for choosing between competing options (\"committed vs. placed vs. reserved resources,\" \"bundle vs. indirect vs. re-record,\" and so on)."}, {"t": "Who this is for", "p": "Welcome & syllabus", "u": "course.html#who-this-is-for", "x": "# You should be comfortable reading C/C++ and have a working mental model of the GPU as \"a thing that turns triangles into pixels.\" You do not need prior Direct3D experience — we build it up era by era. Linear algebra (matrices, vectors) is assumed at the level of \"I know what a model-view-projection matrix is for,\" but every sample uses the same tiny matrix helpers, so you can treat them as a black box if you like."}, {"t": "How to use this course", "p": "Welcome & syllabus", "u": "course.html#how-to-use-this-course", "x": "# Each Part is a separate file in this docs/ folder. Work through them in order — the narrative is cumulative, and later Parts assume the vocabulary built earlier. Each Part contains one or more Modules , and each Module studies one or more samples. Every sample is buildable and runnable. From RotatingCubes/ : PowerShell Copy Each sample's executable lands in its own Out\\ subfolder as Cube<Name>.exe . Run it, watch the cube, then read the source alongside the Module. The source is the primary text; these notes are the lecture that surrounds it. A note on the D3D12 layout. All D3D12 samples live under RotatingCubes\\D3D12\\ , grouped by learning tier in Tier1\\ … Tier4\\ . The tier a sample lives in tells you roughly how far into the D3D12 journey it belongs."}, {"t": "The five eras at a glance", "p": "Welcome & syllabus", "u": "course.html#the-five-eras-at-a-glance", "x": "# Era Year One-sentence identity Big idea introduced D3D7 1999 The GPU is an appliance you configure . Hardware transform & lighting; fixed-function render states. D3D8 2000 Consolidation, and the first programmable shaders. Vertex/index buffers; shader assembly (SM 1.x). D3D9 2002 The programmable pipeline matures. HLSL; vertex & pixel shaders you write. D3D10 2006 Tear it down and rebuild it clean. No fixed function; DXGI; constant buffers; geometry shader. D3D11 2009 The GPU becomes a general compute device. Multithreading; tessellation; DirectCompute. D3D12 2015 You manage the GPU yourself. Command lists/queues, PSOs, root signatures, explicit memory & sync. The single through-line: the GPU went from a fixed appliance you configure , to a programmable processor you feed , to a raw device you manage . Keep that sentence in mind; every Part is one more step along it."}, {"t": "Syllabus", "p": "Welcome & syllabus", "u": "course.html#syllabus", "x": "#"}, {"t": "Part 0 — Orientation", "p": "Welcome & syllabus", "u": "course.html#part-0-orientation", "x": "# The rotating-cube experiment, the anatomy every sample shares, and the vocabulary that survives all five rewrites."}, {"t": "Part I — The Fixed-Function Era", "p": "Welcome & syllabus", "u": "course.html#part-i-the-fixed-function-era", "x": "# D3D7, D3D8. Configuring the GPU by render state; the birth (and mortality) of APIs; where shaders first appear."}, {"t": "Part II — The Programmable Shading Revolution", "p": "Welcome & syllabus", "u": "course.html#part-ii-the-programmable-shading-revolution", "x": "# D3D9 + VertexShader + PixelShader. HLSL arrives; you take ownership of vertex transform and per-pixel color."}, {"t": "Part III — The Great Redesign", "p": "Welcome & syllabus", "u": "course.html#part-iii-the-great-redesign", "x": "# D3D10 + Vertex/Pixel/Geometry. Fixed function removed; DXGI factored out; constant buffers; the geometry shader."}, {"t": "Part IV — Maturity & Generality", "p": "Welcome & syllabus", "u": "course.html#part-iv-maturity-generality", "x": "# D3D11 + Vertex/Pixel/Geometry/Compute/Tessellation. Contexts and multithreading; tessellation; DirectCompute; feature levels."}, {"t": "Part V — Going Explicit: The D3D12 Object Model", "p": "Welcome & syllabus", "u": "course.html#part-v-going-explicit-the-d3d12-object-model", "x": "# D3D12 base + Tier 1. Why D3D12 exists; the new object model; fundamentals, resources, and pipeline basics."}, {"t": "Part VI — Feeding the GPU Efficiently", "p": "Welcome & syllabus", "u": "course.html#part-vi-feeding-the-gpu-efficiently", "x": "# Tier 2 + Tier 3. Explicit memory & submission; multi-engine queues; GPU-driven draws; async compute; bindless; multi-pass rendering."}, {"t": "Part VII — Image Quality & the Modern Pipeline", "p": "Welcome & syllabus", "u": "course.html#part-vii-image-quality-the-modern-pipeline", "x": "# Tier 4 + Shader Model 6. Shadow mapping, MSAA, variable-rate shading; mesh & amplification shaders; DXR ray tracing."}, {"t": "Part VIII — Recording & Querying at Scale", "p": "Welcome & syllabus", "u": "course.html#part-viii-recording-querying-at-scale", "x": "# Tier 5. Multi-threaded recording, bundles, timestamp/statistics queries, predication."}, {"t": "Part IX — Classic Pipeline Mastery", "p": "Welcome & syllabus", "u": "course.html#part-ix-classic-pipeline-mastery", "x": "# Tier 6. Instancing, blending & transparency, the stencil buffer — the output-merger details every real renderer needs."}, {"t": "Part X — Presentation, Devices & Advanced Resources", "p": "Welcome & syllabus", "u": "course.html#part-x-presentation-devices-advanced-resources", "x": "# Tier 7 & 8. HDR & swap-chain color; multi-adapter; pipeline libraries; reserved/tiled resources; debugging & tooling."}, {"t": "Part XI — The Frontier", "p": "Welcome & syllabus", "u": "course.html#part-xi-the-frontier", "x": "# Tier 9 / Agility SDK. SM6.6 dynamic resources, enhanced barriers, sampler feedback, work graphs, DirectStorage, DXR 1.2 (opacity micromaps + shader execution reordering), SM6.10 linear algebra / neural rendering, partial graphics programs & Advanced Shader Delivery."}, {"t": "Part XII — Synthesis", "p": "Welcome & syllabus", "u": "course.html#part-xii-synthesis", "x": "# The arc in one picture; a cross-era retrospective; where the API goes next."}, {"t": "Appendices", "p": "Welcome & syllabus", "u": "course.html#appendices", "x": "# Build/run cheat-sheet · glossary · \"same concept, five names\" terminology table · further reading. On the frontier samples. Part XI covers the Agility-SDK frontier samples in D3D12\\Tier9\\ . The retail ones (SM6.6 dynamic resources, enhanced barriers, sampler feedback, work graphs, DirectStorage) query their capability tier and fall back to a plain cube when the GPU/driver lacks support. The preview ones ( D3D12.RayTracing12 , D3D12.LinearAlgebra , D3D12.PartialPrograms ) vendor the Agility SDK 1.721-preview, preview DXC and preview WARP via fetch-deps.ps1 . When the GPU driver doesn't expose the feature yet, they re-run on WARP so the feature still works on screen. Tiers 1–8 (Parts V–X) all exist and build as well."}, {"t": "Part 0 — Orientation", "p": "Part 0 — Orientation", "u": "part-00-orientation.html#part-0-orientation", "x": "# Part 0 · Before 1999 Before we open a single sample, let's establish the experimental setup, the anatomy every program shares, and a vocabulary of ideas that will survive all five API rewrites. Spend time here; it pays compound interest."}, {"t": "Module 0.1 — The rotating cube as a controlled experiment", "p": "Part 0 — Orientation", "u": "part-00-orientation.html#module-01-the-rotating-cube-as-a-controlled-experiment", "x": "# Every sample in this course renders the same thing: a unit cube, colored at its eight corners, spinning slowly around two axes against a dark blue background. The geometry is identical everywhere — the same eight vertices, the same 36 indices (12 triangles, 2 per face): C Copy Because the output is pinned, everything else in a sample is, by definition, API overhead — the machinery a given Direct3D version demands before it will put those 12 triangles on screen. Reading two samples side by side is therefore a direct measurement of what changed between two eras, and why . Keep a running question in your head as you read: \"Who is doing this work — the runtime, the driver, or me?\" The entire history of Direct3D is the answer to that question shifting, one responsibility at a time, from them to you ."}, {"t": "Why \"shift work onto the programmer\" is progress, not regress", "p": "Part 0 — Orientation", "u": "part-00-orientation.html#why-shift-work-onto-the-programmer-is-progress-not-regress", "x": "# It feels backwards that a newer API makes you write more code. The reason it's progress is that the work the old runtime did for you was done generically — it had to be correct for every program, so it was conservative, it synchronized defensively, and it guessed at your intent. When you take that work over, you can do it specifically : you know your frame structure, so you can synchronize exactly once instead of defensively; you know your memory lifetimes, so you can pack resources tightly. The old runtime's generality was a tax. D3D12 hands you the money back and the responsibility with it. Decision lens — \"Should I use the newest API?\" More control is only worth it if you can spend it. A tool that draws a few thousand triangles will not beat the D3D11 runtime by managing memory by hand — it'll just have more bugs. Reach down an era when you have a bottleneck the runtime's generality is causing (draw-call CPU cost, memory residency, submission threading) and a plan to exploit the control you gain. We'll return to this lens repeatedly."}, {"t": "Module 0.2 — The anatomy every sample shares", "p": "Part 0 — Orientation", "u": "part-00-orientation.html#module-02-the-anatomy-every-sample-shares", "x": "# Strip away the era-specific detail and every sample has the same skeleton. Learn it once and you can navigate any of them: Create a window. Plain Win32: RegisterClass , CreateWindow , a WndProc that quits on ESC . Identical everywhere; we'll never discuss it again. Initialize the device. Acquire the GPU abstraction and a surface to draw into. This is where the eras differ most. Create resources. Vertex data, index data, and (from D3D9 on) shaders and constant storage. The frame loop. Pump window messages; when idle, compute the current rotation angle from elapsed time and render a frame. Render. Clear, set up transforms, draw the cube, and present the result to the screen. Here's the same frame loop, essentially unchanged from D3D7 to D3D12: C++ Copy The Render(t) function is where the whole story lives. In D3D7 it's a dozen lines. In D3D12 it orchestrates command allocators, records a command list, inserts resource barriers, submits to a queue, waits on a fence, and presents. Same five words in the loop; wildly different amounts of ceremony inside."}, {"t": "Module 0.3 — Vocabulary that persists across every era", "p": "Part 0 — Orientation", "u": "part-00-orientation.html#module-03-vocabulary-that-persists-across-every-era", "x": "# These concepts predate D3D7 and outlive D3D12. The names and objects change, but the ideas are constant. When an era \"introduces\" something, it's usually making an old implicit idea explicit. Vertex — a point with attributes (position, color, texture coordinates). Primitive — how vertices assemble into shapes; we always use a triangle list . Index buffer — reuse shared vertices (a cube has 8 corners but 36 triangle corners) by referencing them by number. Transform — the matrices that move geometry from model space, to the camera's view, to the 2D screen. The model-view-projection (MVP) matrix is the product of all three. Rasterization — turning a projected triangle into the pixels it covers. Always done by fixed-function silicon; never programmable (until ray tracing sidesteps it entirely in Part VII). Depth buffer (Z-buffer) — a per-pixel depth so nearer surfaces hide farther ones. Every sample has one. Render target — the image being drawn into. The swap chain (from D3D8 on) holds the front/back buffers and presents the finished frame. The frame — clear → set transforms → draw → present, sixty times a second."}, {"t": "The one genuinely new idea: the programmable shader", "p": "Part 0 — Orientation", "u": "part-00-orientation.html#the-one-genuinely-new-idea-the-programmable-shader", "x": "# If you internalize a single arc, make it this one. In D3D7, the pipeline is a fixed function : you set state (a matrix here, a lighting flag there) and the silicon does a hardwired sequence of operations. Starting in D3D8/D3D9, stages of that pipeline become programmable — you supply a small program (a shader ) that the GPU runs per vertex or per pixel. Everything after D3D9 is, in a sense, the consequences of that one idea: If vertices and pixels can run programs, why not whole new stages? → geometry (D3D10), tessellation (D3D11), mesh/amplification (D3D12). If the GPU runs programs, why only graphics programs? → compute (D3D11). If the GPU is a programmable processor, why does the driver babysit it so much? → the explicit model of D3D12. Hold that thread. Now let's go back to 1999, when none of it existed yet."}, {"t": "Part I — The Fixed-Function Era", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#part-i-the-fixed-function-era", "x": "# Part I · D3D7 · D3D8 2 samples in this part D3D7.Basic D3D8.Basic In this era the GPU is an appliance . You don't program it; you configure it. There's a fixed sequence of operations baked into silicon — transform, light, rasterize, blend — and your job is to set the knobs: this matrix, that lighting flag, this cull mode. Then you hand it triangles and it does the rest. Two samples anchor this Part: D3D7 ( RotatingCubes\\D3D7 ) and D3D8 ( RotatingCubes\\D3D8 )."}, {"t": "Module 1 — D3D7: Configuring an Appliance", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#module-1-d3d7-configuring-an-appliance", "x": "#"}, {"t": "The problem it solved", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#the-problem-it-solved", "x": "# In 1999, consumer GPUs had just gained hardware transform & lighting (T&L) — the ability to do vertex math on the card instead of the CPU. Direct3D 7 exists to expose that. Its entire worldview: the application describes what state the pipeline should be in , and the fixed-function hardware executes a predetermined program using that state."}, {"t": "How it works", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#how-it-works", "x": "# D3D7 is joined at the hip to DirectDraw , the older 2D surface API. You don't get a tidy \"swap chain\"; you allocate raw surfaces and blit them yourself. Look at the setup in D3D7.Basic\\main.cpp : C++ Copy Notice there is no shader, no input layout, no constant buffer . Instead, the pipeline is steered by render states and transforms : C++ Copy Drawing is likewise \"here are vertices, here's their format, go\": C++ Copy The D3DFVF_LVERTEX is a Flexible Vertex Format flag: a bitmask that tells the fixed-function pipeline what's in each vertex (here: position + a pre-lit color). The pipeline has hardcoded slots for \"position,\" \"color,\" \"normal,\" \"texture coords\" — you can only describe vertices in its vocabulary. And because DirectDraw doesn't present for you, the frame ends with a manual blit from the back buffer to the window's client rectangle: C++ Copy"}, {"t": "When to use it (and when not)", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#when-to-use-it-and-when-not", "x": "# This is a history lesson, not a recommendation: never start new work in D3D7. It's here to establish the baseline. But the mental model — \"configure a fixed pipeline with state\" — is worth understanding, because it's exactly what the programmable pipeline replaced, and traces of it survive (depth state, blend state, and rasterizer state in D3D12 are still \"render states,\" just grouped into immutable objects)."}, {"t": "Historical \"why now?\"", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#historical-why-now", "x": "# D3D7 couldn't have shaders because the hardware couldn't run them yet. The API is a faithful mirror of 1999 silicon: fixed T&L, fixed lighting, fixed blending. The DirectDraw coupling reflects an even older world where 2D and 3D were separate concerns bolted together. Decision lens — reading legacy fixed-function code. When you meet a wall of SetRenderState calls in old code, don't try to map each one to a modern equivalent line-for-line. Instead ask \"what stage is this configuring?\" Lighting states → what a vertex/pixel shader would now compute. Texture-stage states → what a pixel shader would now do. Framing it by pipeline stage makes ancient code legible."}, {"t": "Module 2 — D3D8: Consolidation and the First Cracks", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#module-2-d3d8-consolidation-and-the-first-cracks", "x": "#"}, {"t": "The problem it solved", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#the-problem-it-solved_1", "x": "# D3D8 (2000) had two jobs. First, consolidation : it merged DirectDraw and Direct3D into a single \"DirectX Graphics\" API, killing the awkward surface juggling of Module 1. Second — and this is the earthquake — it introduced the first programmable shaders (vertex and pixel shaders, in assembly, \"shader model 1.x\"). Our sample deliberately stays fixed-function so you can see the consolidation cleanly; we'll meet real shaders in Part II."}, {"t": "How it works", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#how-it-works_1", "x": "# The surface circus is gone. You describe how you want to present, and the runtime manages the buffers: C++ Copy Compare that to D3D7's manual primary/back/Z-buffer/clipper dance — a whole category of code simply evaporated. Presenting is now one call: C++ Copy D3D8 also formalizes vertex and index buffers as GPU resources you fill once and reuse, instead of passing raw pointers each draw: C++ Copy There's a wonderful fossil in the draw code that foreshadows the whole next era: C++ Copy The method is literally called SetVertexShader , but here we hand it an FVF bitmask — \"use the fixed-function vertex pipeline.\" The socket for programmable shaders has been wired in; we're just not plugging anything into it yet."}, {"t": "A side lesson: APIs are mortal", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#a-side-lesson-apis-are-mortal", "x": "# Our D3D8 sample can't use the Windows SDK's headers, because d3d8.h was removed from the modern SDK. The sample vendors the Wine project's headers and loads d3d8.dll at runtime: C++ Copy The DLL still ships with Windows for compatibility, but Microsoft stopped supporting development against it. That's a real engineering lesson: an API's runtime and its SDK have different lifetimes. Code you ship may keep running for decades after you can no longer easily build against that API."}, {"t": "When to use it", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#when-to-use-it", "x": "# Again — never, for new work. But D3D8 marks the exact inflection point of this entire course: it's the last era where \"just configure the fixed pipeline\" is the whole story, and the first where the alternative exists. Everything from Part II onward is life after that fork."}, {"t": "Historical \"why now?\"", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#historical-why-now_1", "x": "# Two forces converged around 2000. Hardware gained programmable vertex units (NVIDIA's GeForce 3 shipped pixel shaders in 2001), so the API needed a way to express programs. And the DirectDraw/Direct3D split had become pure friction now that all rendering went through the 3D pipeline. D3D8 resolved both at once. Decision lens — recognizing a \"consolidation\" release. D3D8 is a pattern you'll see again (D3D10, D3D12): a release that removes an entire subsystem and folds its job into a cleaner model. When evaluating whether to adopt such a release, the cost isn't learning the new features — it's that the old escape hatches are gone. D3D8 apps couldn't fall back to raw DirectDraw tricks. That forced simplicity is the point, but it's also the migration pain."}, {"t": "Part I in one paragraph", "p": "Part I — The Fixed-Function Era", "u": "part-01-fixed-function-era.html#part-i-in-one-paragraph", "x": "# The fixed-function era treats the GPU as a configurable appliance: you set render states and transforms, hand over triangles, and hardwired silicon does the rest. D3D7 shows the model at its most raw (manual DirectDraw surfaces); D3D8 cleans it up (swap-chain-like presentation, vertex/index buffers) and quietly installs the socket — SetVertexShader — into which the next era will plug real programs. The stage is set for the revolution."}, {"t": "Part II — The Programmable Shading Revolution", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#part-ii-the-programmable-shading-revolution", "x": "# Part II · D3D9 3 samples in this part D3D9.Basic VertexShader PixelShader This is the pivot on which the whole course turns. In Part I you configured a fixed pipeline. Starting now, you write programs the GPU runs — one per vertex, one per pixel. Direct3D 9 (2002) is where this becomes practical and pleasant, thanks to HLSL , the High-Level Shading Language, which lets you write shaders in C-like code instead of GPU assembly. Three samples anchor this Part, all in RotatingCubes\\D3D12\\Tier1 's ancestors at the repo root: D3D9 (fixed-function baseline), D3D9.VertexShader , and D3D9.PixelShader ."}, {"t": "Module 3 — D3D9: HLSL and the Programmable Pipeline", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#module-3-d3d9-hlsl-and-the-programmable-pipeline", "x": "#"}, {"t": "The problem it solved", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#the-problem-it-solved", "x": "# Shader assembly (D3D8's vs_1_1 ) was miserable to write and impossible to maintain — register allocation by hand, no functions, no readable math. D3D9's answer was twofold: richer shader models ( vs_2_0 / vs_3_0 , ps_2_0 / ps_3_0 ) and HLSL with a runtime compiler ( D3DCompile / fxc ) so you could write: HLSL Copy D3D9 is also the era's workhorse: it powered a decade of games and is the point where \"modern\" real-time graphics thinking begins."}, {"t": "The baseline: D3D9 (still fixed-function)", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#the-baseline-d3d9-still-fixed-function", "x": "# Crucially, D3D9 kept the fixed-function pipeline. The base D3D9\\D3D9.Basic\\main.cpp looks almost identical to D3D8 — set matrices, set an FVF, draw: C++ Copy This matters: D3D9 is a transitional API. Fixed function and programmable shaders coexist, and you could adopt shaders incrementally. That gentle on-ramp is a big reason D3D9 was adopted so widely and lived so long."}, {"t": "How programmable shading works: D3D9.VertexShader", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#how-programmable-shading-works-d3d9vertexshader", "x": "# Now compare D3D9.VertexShader\\main.cpp . Instead of SetFVF , we compile a vertex shader from HLSL at runtime and bind it. The shader replaces the fixed-function transform — computing clip-space position is now our job: HLSL Copy Because we own the vertex program, we can do things the fixed pipeline never could — like displacing every vertex by a time-varying sine wave so the cube appears to breathe. That's the payoff: expressiveness . The fixed pipeline had a menu; the shader is a blank page. The host code changes to match. We compile HLSL, create shader objects, describe the vertex layout with a vertex declaration (FVF's more flexible successor), and feed the shader its constants: C++ Copy That SetVertexShader(g_vs) is the same method that took an FVF bitmask in D3D8. The socket now has a program in it. The revolution, in one line. Note the constant registers ( c0 , c4 ). Shader inputs that aren't per-vertex — matrices, time, light directions — are uploaded into numbered constant registers. This is clumsy (you count float4 slots by hand) and D3D10 will replace it with constant buffers . But the idea — \"shaders need uniform inputs\" — is born here."}, {"t": "D3D9.PixelShader: owning the per-pixel result", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#d3d9pixelshader-owning-the-per-pixel-result", "x": "D3D9.PixelShader : owning the per-pixel result # The pixel-shader sample tells the mirror-image story for color. The fixed-function pipeline interpolated vertex colors and did a fixed set of texture blends; a ps_3_0 pixel shader lets you compute each pixel's color with arbitrary math (an animated procedural pattern, in the sample). Same lesson, different stage: a menu becomes a blank page."}, {"t": "When to use programmable shaders", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#when-to-use-programmable-shaders", "x": "# By D3D9's design, the honest answer became \"almost always.\" Any per-vertex deformation (skinning, morphing, wind, water), any per-pixel effect (lighting models beyond the fixed one, normal mapping, procedural texturing) requires shaders. The fixed pipeline remained only for the simplest UI/blit work."}, {"t": "When not to (in the D3D9 era specifically)", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#when-not-to-in-the-d3d9-era-specifically", "x": "# Old hardware. In 2002–2005, plenty of cards had weak or no ps_2_0+ support. Shipping code often kept a fixed-function fallback path. (This concern died with D3D10, which mandated shaders.) Trivial rendering. If you're just blitting a fullscreen image, the fixed-function path was less code. That calculus flips in D3D10 too."}, {"t": "Trade-offs & decision guidance", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#trade-offs-decision-guidance", "x": "# The cost of shaders is a new compilation and asset pipeline (HLSL must be compiled, cached, and versioned), plus the discipline of feeding constants correctly. The benefit is unbounded expressiveness and moving work onto massively parallel GPU units. In the D3D9 era the trade was \"more pipeline complexity for effects you literally cannot do otherwise\" — an easy yes for anything visually ambitious. Decision lens — fixed-function vs. programmable (D3D9 framing). Ask: does the effect fit the fixed-function menu? Flat or vertex-colored geometry, single-texture, standard lighting → fixed function is fine and simpler. Anything else → shaders. After D3D10 this lens is retired, because fixed function is gone and the question becomes moot."}, {"t": "Historical \"why now?\"", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#historical-why-now", "x": "# By 2002 programmable hardware was mainstream (GeForce 3/4, Radeon 8500+), and the assembly-only D3D8 model had proven too painful for real production. HLSL (and NVIDIA's parallel Cg) made shaders writable by normal engineers . That usability breakthrough — not the hardware alone — is what made the revolution stick."}, {"t": "Part II in one paragraph", "p": "Part II — The Programmable Shading Revolution", "u": "part-02-programmable-shading.html#part-ii-in-one-paragraph", "x": "# D3D9 turns the shader socket D3D8 installed into a practical, high-level tool. HLSL lets you write the per-vertex and per-pixel programs the GPU runs, replacing fixed-function transform and coloring with blank-page expressiveness — a breathing cube, a procedural surface. Constants enter shaders through numbered registers (soon to become constant buffers), and — critically — fixed function still coexists, making D3D9 a gentle, long-lived on-ramp into the programmable world. Next, D3D10 will take the radical step of throwing the fixed pipeline away entirely."}, {"t": "Part III — The Great Redesign", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#part-iii-the-great-redesign", "x": "# Part III · D3D10 4 samples in this part D3D10.Basic VertexShader PixelShader GeometryShader Direct3D 10 (2006, Windows Vista) is the boldest release in the whole timeline. It didn't extend the D3D9 model — it replaced it. Fixed function: gone. Legacy state juggling: gone. In their place, a clean, strict, shader-only pipeline built on a new foundation ( DXGI ) that survives, largely unchanged, into D3D12 today. If D3D9 was a gentle on-ramp, D3D10 was a hard reset. Anchoring samples (repo root): D3D10 , plus the stage showcases D3D10.VertexShader , D3D10.PixelShader , and D3D10.GeometryShader ."}, {"t": "Module 4 — D3D10: Tearing It Down and Rebuilding", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#module-4-d3d10-tearing-it-down-and-rebuilding", "x": "#"}, {"t": "The problem it solved", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#the-problem-it-solved", "x": "# D3D9's API had accumulated a decade of barnacles: fixed-function and programmable paths, dozens of loosely-validated render states, per-call driver overhead from re-validating everything constantly. D3D10 (which required new hardware and a new driver model, WDDM) took the opportunity to design the API Microsoft wished they'd had all along: No fixed function. Every draw must have a vertex and pixel shader. This halved the API surface and the driver's validation burden. Constant buffers replace numbered constant registers. DXGI (DirectX Graphics Infrastructure) is factored out as a separate, version-independent layer for adapters, swap chains, and presentation. Strict, up-front validation. State is grouped and validated when created, not re-checked every draw. A new stage: the geometry shader."}, {"t": "How it works: the new foundation", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#how-it-works-the-new-foundation", "x": "# The very first thing you notice in D3D10\\D3D10.Basic\\main.cpp is DXGI . The swap chain is described by a DXGI_SWAP_CHAIN_DESC and created alongside the device: C++ Copy Why does this matter? DXGI is the piece that outlives every D3D version. The DXGI_FORMAT_R8G8B8A8_UNORM , the swap chain, Present() — you'll see the exact same DXGI types in the D3D12 samples in Part V. Microsoft factored out the \"talk to the display and the adapter\" concern so it could evolve the rendering API (D3D10 → 11 → 12) without re-inventing presentation each time. When you learn DXGI once here, you've learned it for good."}, {"t": "Render targets as views", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#render-targets-as-views", "x": "# D3D10 also formalizes the view concept. A resource (a texture) is separate from how you interpret it. You don't render \"to a texture\"; you render to a render-target view of it, and you'd sample it through a shader-resource view : C++ Copy This resource/view split is fundamental and permanent — it's exactly how D3D12's descriptor heaps work, just made explicit and manual there."}, {"t": "Constant buffers: the end of numbered registers", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#constant-buffers-the-end-of-numbered-registers", "x": "# Remember D3D9's SetVertexShaderConstantF(0, &mvp, 4) — counting float4 slots by hand? D3D10 replaces it with a real object. The shader declares a cbuffer ; the host fills a buffer and binds it: HLSL Copy C++ Copy Why this is better: you update a whole struct of related constants in one shot, the layout is described once by the shader, and the runtime can manage the upload efficiently. Constant buffers are so right that they're essentially unchanged in D3D11 and D3D12."}, {"t": "The input layout is validated against the shader", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#the-input-layout-is-validated-against-the-shader", "x": "# D3D10 ties the vertex layout to the compiled shader's expected inputs, catching mismatches up front: C++ Copy This \"validate against the shader signature\" idea is the seed of D3D12's ID3D12PipelineState , which bundles the layout, shaders, and all render state into one pre-validated immutable object."}, {"t": "The new stage: the geometry shader (D3D10.GeometryShader)", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#the-new-stage-the-geometry-shader-d3d10geometryshader", "x": "The new stage: the geometry shader ( D3D10.GeometryShader ) # D3D10's headline new capability is a programmable stage between vertex and pixel shading that operates on whole primitives and can emit new ones. Our sample uses it to explode the cube's faces along their normals: HLSL Copy"}, {"t": "When to use the geometry shader", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#when-to-use-the-geometry-shader", "x": "# Genuinely useful for: point-sprite expansion (1 vertex → a quad), generating normals/adjacency, single-pass rendering to cube-map faces, and small primitive-level tricks. But note the caveat that shaped the next decade:"}, {"t": "When not to use it — a cautionary tale", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#when-not-to-use-it-a-cautionary-tale", "x": "# The geometry shader turned out to be slow on most hardware. Its ability to amplify geometry (emit more vertices than it received) maps badly onto GPU architectures — it forces serialization and buffering. In practice, teams learned to avoid the GS for anything performance-sensitive. This is why D3D12 later introduced mesh & amplification shaders (Part VII): a redesign of programmable geometry amplification that actually runs fast. The geometry shader is a rare example of a feature that shipped, disappointed, and was eventually superseded rather than extended. Decision lens — should I reach for the geometry shader? Default to no for hot paths. Consider it only when (a) the amplification factor is tiny or zero, (b) the alternative (extra draw calls, compute pre-pass) is clearly worse, and (c) you've measured. If you're on D3D12-class hardware and need real geometry amplification, jump straight to mesh shaders instead."}, {"t": "Trade-offs of the whole D3D10 redesign", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#trade-offs-of-the-whole-d3d10-redesign", "x": "# Gained: a clean, strict, lower-overhead API; constant buffers; DXGI; shader-validated layouts; the resource/view model. A far better foundation . Paid: no backward compatibility with fixed-function code (a hard port for legacy engines), and it required Vista + new hardware, which slowed adoption. Verdict: history vindicated it. Nearly every good idea in D3D10 is still present in D3D12. The redesign was worth the disruption."}, {"t": "Historical \"why now?\"", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#historical-why-now", "x": "# Vista's new driver model (WDDM) was a once-in-a-decade chance to break compatibility. Microsoft spent it deliberately, shipping the API that hardware had outgrown D3D9's abstractions for. D3D10 is the \"measure twice, cut once\" release — and the cut has held for nearly twenty years."}, {"t": "Part III in one paragraph", "p": "Part III — The Great Redesign", "u": "part-03-great-redesign.html#part-iii-in-one-paragraph", "x": "# D3D10 rebuilds Direct3D from the studs: fixed function is deleted, every draw is shader-driven, constants become first-class constant buffers , resources are accessed through views , layouts are validated against shaders , and presentation is factored into DXGI — the durable layer you'll still be using in D3D12. Its new geometry shader is a lesson in humility (powerful but slow, later superseded). The era's real gift is a clean foundation; D3D11 will build generality and multithreading on top of it."}, {"t": "Part IV — Maturity & Generality", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#part-iv-maturity-generality", "x": "# Part IV · D3D11 4 samples in this part D3D11.Basic VertexShader ComputeShader Tessellation Direct3D 11 (2009, Windows 7) is not a redesign — it's a refinement and expansion of D3D10's clean foundation. It's arguably the most beloved release in the timeline: modern enough to do everything, forgiving enough to be productive, and still in heavy use today. Two additions define it — the pipeline grows two new tricks ( tessellation and compute ), and the API grows up to support multithreaded rendering and feature levels . Anchoring samples (repo root): D3D11 plus the showcases D3D11.VertexShader , .PixelShader , .GeometryShader , .ComputeShader , and .Tessellation ."}, {"t": "Module 5 — D3D11: The GPU as a General Compute Device", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#module-5-d3d11-the-gpu-as-a-general-compute-device", "x": "#"}, {"t": "The problem it solved", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#the-problem-it-solved", "x": "# D3D10 was clean but had two notable gaps. First, its rendering was single-threaded at the API level — a real bottleneck as CPUs went multi-core and scenes grew to tens of thousands of draw calls. Second, using the GPU for non-graphics work was awkward. D3D11 addresses both, and adds hardware tessellation for good measure."}, {"t": "Device vs. context: the split that enables threading", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#device-vs-context-the-split-that-enables-threading", "x": "# D3D10 had one object that was both \"the GPU\" and \"the thing you issue commands to.\" D3D11 splits them: The device ( ID3D11Device ) creates resources. It's free-threaded — any thread can call it. The immediate context ( ID3D11DeviceContext ) issues commands to the GPU. Optional deferred contexts record command lists on worker threads, to be replayed later on the immediate context. You can see the split at creation in D3D11.ComputeShader\\main.cpp : C++ Copy Why the split matters: it's the conceptual seed of D3D12. Once \"create a resource\" and \"issue a command\" are different objects, you can record commands on many threads at once. D3D11's deferred contexts were a first, somewhat limited attempt; D3D12's command lists (Part V) are the full realization. If you understand why D3D11 split device from context, D3D12's command-list model will feel inevitable rather than alien."}, {"t": "Feature levels: one API, many hardware generations", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#feature-levels-one-api-many-hardware-generations", "x": "# D3D11 introduced feature levels — a brilliant pragmatic idea. The D3D11 API can drive D3D9-, D3D10-, or D3D11-class hardware; you query what the actual GPU supports and scale accordingly: C++ Copy This decoupled API version from hardware capability , so developers could adopt the modern API without abandoning older GPUs. Feature levels carry forward into D3D12."}, {"t": "New trick 1: Tessellation (D3D11.Tessellation)", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#new-trick-1-tessellation-d3d11tessellation", "x": "New trick #1: Tessellation ( D3D11.Tessellation ) # Tessellation adds three pipeline stages that subdivide geometry on the GPU: the hull shader (sets how finely to subdivide), the fixed-function tessellator , and the domain shader (positions each generated vertex). Our sample subdivides each cube face and bulges it toward a sphere: HLSL Copy When to use tessellation: dynamic level-of-detail (more triangles up close, fewer far away), displacement mapping (a heightmap turns a flat quad into terrain on the GPU), and smooth curved surfaces from coarse control meshes. It shines when you want adaptive geometry density without storing or transferring the dense mesh. When not to: if your geometry density is uniform and known, just author the mesh at the right density — tessellation adds pipeline complexity for no gain. And like the geometry shader, over-tessellating (tiny sub-pixel triangles) wrecks performance because GPUs shade pixels in 2×2 quads. Decision lens — adaptive geometry. Choose tessellation for continuous LOD driven by distance/screen-size. Choose discrete authored LOD meshes when you have a few known levels and want predictable cost. Choose mesh shaders (Part VII) if you're "}, {"t": "New trick 2: DirectCompute (D3D11.ComputeShader)", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#new-trick-2-directcompute-d3d11computeshader", "x": "New trick #2: DirectCompute ( D3D11.ComputeShader ) # This is D3D11's most far-reaching addition: the compute shader ( cs_5_0 ), which runs general-purpose parallel programs on the GPU outside the draw pipeline. No vertices, no pixels — just threads, thread-groups, and read/write buffers/textures ( UAVs , unordered-access views). Our sample dispatches a compute shader that writes an animated pattern into a texture, which the cube then samples: HLSL Copy C++ Copy Note the explicit unbind of the UAV before the texture is sampled: the same resource can't be bound for writing and reading simultaneously. D3D11 tracks these hazards for you (it inserts the necessary sync) — remember that, because in D3D12 tracking that hazard becomes your job via resource barriers. When to use compute: post-processing (blur, bloom, tone-mapping), particle simulation, physics, culling, image processing, building acceleration structures — anything data-parallel that isn't naturally \"draw triangles.\" Compute is the foundation of modern GPU-driven rendering. When not to: for work that maps cleanly onto the raster pipeline (e.g. a fullscreen pass that reads and writes one target), a pixel shader over a fullscr"}, {"t": "Historical \"why now?\"", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#historical-why-now", "x": "# Multi-core CPUs made single-threaded submission the bottleneck, so the device/context split and deferred contexts appeared. GPUs had become fully general parallel processors, so DirectCompute exposed that generality. And a fragmented hardware market made feature levels a necessity. D3D11 is what \"programmable GPU\" looks like once the idea is fully mature — which is precisely why the next step had to be about overhead , not features."}, {"t": "Part IV in one paragraph", "p": "Part IV — Maturity & Generality", "u": "part-04-maturity-generality.html#part-iv-in-one-paragraph", "x": "# D3D11 perfects the programmable-GPU model: it splits the free-threaded device from the command-issuing context (enabling multithreaded submission), adds tessellation for adaptive GPU geometry, and — most importantly — adds compute shaders , turning the GPU into a general parallel processor for work that has nothing to do with triangles. Feature levels let one API span many GPU generations. Notice the recurring theme: D3D11 still tracks resource hazards and synchronizes for you . That convenience is the last thing D3D12 will take back — in exchange for the CPU efficiency that features alone could no longer buy."}, {"t": "Part V — Going Explicit: The D3D12 Object Model", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#part-v-going-explicit-the-d3d12-object-model", "x": "# Part V · D3D12 · Tier 1 5 samples in this part Fundamentals Textures VertexShader PixelShader Nuklear Everything so far has followed one arc: give the programmer more control over what the GPU computes . Direct3D 12 (2015, Windows 10) changes the subject entirely. The pipeline barely changes. What changes is who does the bookkeeping . For twenty years the driver tracked resource states, synchronized the CPU and GPU, validated your calls, and managed memory for you . D3D12 hands all of that back. This Part explains why anyone would want that, and introduces the object model through our Tier 1 samples. Anchoring samples: D3D12\\Tier1\\ — D3D12.Fundamentals (the template), D3D12.Textures , D3D12.VertexShader , D3D12.PixelShader , D3D12.Nuklear ."}, {"t": "Module 6 — Why D3D12 Exists (the case for explicitness)", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#module-6-why-d3d12-exists-the-case-for-explicitness", "x": "#"}, {"t": "The problem it solved", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#the-problem-it-solved", "x": "# By 2015 the bottleneck in high-end rendering was no longer the GPU — it was the CPU-side driver . Every D3D11 draw call ran through driver code that validated arguments, tracked which resources were bound where, decided when to allocate or rename memory, and inserted synchronization. On a scene with tens of thousands of draws, that overhead dominated, and it was single-threaded and unpredictable (the driver might decide to compile a shader or allocate memory mid-frame, causing a hitch). D3D12's thesis: the application knows more than the driver. You know which resources you'll use, when you're done with them, and how your frames are structured. So D3D12 removes the driver's guesswork and makes you state your intentions explicitly. In return you get lower, more predictable overhead and true multithreaded submission ."}, {"t": "The four things you now own", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#the-four-things-you-now-own", "x": "# Resource state — you transition resources between states with barriers (the driver no longer tracks it). CPU/GPU synchronization — you signal and wait on fences (no automatic sync). Memory — you (can) place resources in heaps you allocate. Pipeline configuration — you bake almost all render state into an immutable pipeline state object up front, instead of setting it piecemeal per draw."}, {"t": "When to use D3D12 (and when not to)", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#when-to-use-d3d12-and-when-not-to", "x": "# Use D3D12 when: you're CPU-bound on draw-call submission; you need multithreaded command recording; you want predictable frame times (no driver hitches); you need features only D3D12 exposes (mesh shaders, DXR raytracing, work graphs); or you're building an engine that will amortize the complexity over many titles. Do not use D3D12 when: you're GPU-bound (D3D12 won't make the GPU faster); your scene is small (a few hundred draws — D3D11's overhead is irrelevant); or you're a small team optimizing for time-to-ship over last-10%-performance. D3D11 remains an excellent, fully modern choice. Explicitness is a cost you pay to buy CPU efficiency and control — only worthwhile if you need what it buys. Decision lens — D3D11 vs. D3D12. The honest default is D3D11 unless you can name the specific thing D3D12 gives you. \"It's newer\" is not a reason. \"We're CPU-bound at 12,000 draw calls and need to record them on 8 threads\" is."}, {"t": "Module 7 — Tier 1: The D3D12 Skeleton", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#module-7-tier-1-the-d3d12-skeleton", "x": "# Every D3D12 program shares a skeleton. D3D12.Fundamentals is our reference implementation of it (written in C with COBJMACROS , so calls read ID3D12X_Method(obj, ...) ). Learn this skeleton once and every other D3D12 sample becomes readable."}, {"t": "Queues, allocators, and command lists", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#queues-allocators-and-command-lists", "x": "# D3D11's single \"context\" splits into three D3D12 objects: Command queue — the GPU's actual work intake. You ExecuteCommandLists onto it. Command allocator — the backing memory that commands are recorded into. Command list — the recording surface you write commands to, then Close and submit. C Copy Why three objects? Because the split is what enables threading and reuse. Many threads each record into their own allocator/list, then one queue consumes them all. Our teaching sample stays single-threaded for clarity, but the object model is the multithreaded one."}, {"t": "Fences: you synchronize now", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#fences-you-synchronize-now", "x": "# There is no automatic \"wait until the GPU is done.\" You do it yourself with a fence — a shared counter the GPU increments and the CPU polls: C Copy This busy-wait-per-frame is deliberately the simplest correct thing (a real engine waits on an event and pipelines 2–3 frames deep instead of stalling). The lesson: CPU/GPU synchronization is now application code. Get it wrong and you either corrupt data (CPU races ahead) or destroy performance (CPU stalls too often)."}, {"t": "Resource barriers: you track state now", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#resource-barriers-you-track-state-now", "x": "# The single most characteristic D3D12 code is the resource barrier . Each frame the back buffer must move from PRESENT to RENDER_TARGET to draw, then back: C Copy Remember D3D11's compute sample, where the runtime unbound the UAV and inserted sync for you ? This is that same hazard tracking — now handed to you. Barriers are also where you tell the GPU to flush caches and wait for prior work, so getting them wrong causes flickering, corruption, or GPU hangs. (The Tier-1 UI even counts barriers per frame to make the cost visible.)"}, {"t": "PSOs and root signatures: bake state up front", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#psos-and-root-signatures-bake-state-up-front", "x": "# D3D11 set rasterizer state, blend state, shaders, and input layout as separate calls that the driver reconciled at draw time (sometimes recompiling shaders mid-frame — a hitch). D3D12 bakes almost all of it into one immutable pipeline state object created ahead of time: C Copy The root signature is the separate, small declaration of what inputs the shaders receive (constants, descriptor tables, samplers) — think of it as the function signature for your pipeline. Fundamentals uses the cheapest possible input: 16 root constants for the MVP matrix, no constant buffer at all: C Copy Why bake state? Because compiling a full pipeline is expensive, and doing it predictably at load time eliminates the mid-frame hitches D3D11 could suffer. The cost: a combinatorial explosion of PSOs (every shader × blend × topology combination is a separate object), which becomes a real content-pipeline concern (addressed later by pipeline libraries, Part X). Decision lens — how to feed shader data in D3D12. Root constants for tiny, per-draw data (a matrix, a few floats) — cheapest, no descriptor. Root descriptors for a single CBV/SRV/UAV used often. Descriptor tables for everything else (textures, arrays"}, {"t": "Descriptor heaps", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#descriptor-heaps", "x": "# Views (RTV, DSV, SRV, CBV) live in descriptor heaps — GPU-visible arrays of resource descriptors that you allocate and index yourself: C Copy D3D12.Textures is the first sample to use a shader-visible SRV heap (to bind a texture); the base cube only needs RTV/DSV heaps. This heap-and-index model is the seed of bindless rendering (Part VI)."}, {"t": "Historical \"why now?\"", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#historical-why-now", "x": "# Multithreaded CPUs, ballooning draw-call counts, and the console world (where fixed hardware made low-level APIs like the PlayStation's GNM hugely successful) all pushed toward explicitness. AMD's Mantle proved developers wanted it; D3D12, Vulkan, and Metal all landed within a couple of years carrying the same philosophy. D3D12 is D3D11's pipeline with the driver's safety rails removed — a trade you make consciously, feature by feature."}, {"t": "Part V in one paragraph", "p": "Part V — Going Explicit: The D3D12 Object Model", "u": "part-05-going-explicit-d3d12.html#part-v-in-one-paragraph", "x": "# D3D12 keeps the pipeline and changes the contract : you now own resource-state transitions ( barriers ), CPU/GPU sync ( fences ), memory, and up-front pipeline baking ( PSOs + root signatures + descriptor heaps ). The payoff is lower, predictable CPU overhead and multithreaded submission; the price is that mistakes which D3D11 quietly prevented now corrupt frames or hang the GPU. The D3D12.Fundamentals skeleton — queue/allocator/list, signal_and_wait , the PRESENT↔RENDER_TARGET barrier pair, root-constant MVP — is the vocabulary every later Part builds on."}, {"t": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#part-vi-feeding-the-gpu-memory-copies-and-gpu-driven-work", "x": "# Part VI · Tier 2 · Tier 3 9 samples in this part PlacedResources CopyQueue IndirectDraw GeometryShader Tessellation ComputeShader ComputeAsync Bindless DeferredMRT Tier 1 got a triangle on screen the explicit way. But real engines spend most of their D3D12 effort on two problems the skeleton ignored: where resources live in memory and how data gets there , and how to issue thousands of draws efficiently — ideally from the GPU itself. Tier 2 is about memory and copies; Tier 3 is about compute-driven rendering. Both are where D3D12's explicitness starts paying real dividends. Anchoring samples: D3D12\\Tier2\\ ( PlacedResources , CopyQueue , IndirectDraw , GeometryShader , Tessellation ) and D3D12\\Tier3\\ ( ComputeShader , ComputeAsync , Bindless , DeferredMRT )."}, {"t": "Module 8 — Tier 2: Memory & Data Movement", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#module-8-tier-2-memory-data-movement", "x": "#"}, {"t": "The problem it solved", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#the-problem-it-solved", "x": "# D3D11 allocated memory for every resource you created and copied your data up for you — convenient, but opaque and often wasteful. D3D12 exposes the machinery so you can sub-allocate , alias , and stream data on your own terms, and move copies onto dedicated hardware so they don't stall rendering."}, {"t": "Placed resources (D3D12.PlacedResources)", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#placed-resources-d3d12placedresources", "x": "Placed resources ( D3D12.PlacedResources ) # A committed resource (the Tier-1 default) gets its own implicit heap allocation. A placed resource is created at an offset into a heap you allocated yourself : Flow When to use: sub-allocating many small resources from one big heap (far cheaper than many committed allocations); aliasing two resources that are never used at the same time onto the same memory (a transient shadow buffer and a transient blur buffer can share bytes); and any streaming system where you manage a memory budget yourself. When not to: for a handful of long-lived resources, committed resources are simpler and the allocation overhead is irrelevant. Placement is a tool for scale and memory pressure , not a default. Decision lens — committed vs. placed. Committed for \"a few big things that live forever.\" Placed (or a sub-allocator built on it) for \"many things,\" \"tight memory budget,\" or \"resources that can share space because their lifetimes don't overlap.\""}, {"t": "The copy queue (D3D12.CopyQueue)", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#the-copy-queue-d3d12copyqueue", "x": "The copy queue ( D3D12.CopyQueue ) # D3D12 has three queue types: direct (graphics + everything), compute , and copy . The copy queue maps to dedicated DMA hardware that shuttles data over PCIe in parallel with the GPU rendering: Flow When to use: background streaming of textures/meshes in an open-world game, uploading next frame's data while this frame renders — anything where you don't want a big transfer blocking the graphics queue. The cross-queue fence is how you make the graphics queue wait for the copy to finish. When not to: a small one-time upload at load time doesn't need its own queue; just upload on the direct queue. The copy queue earns its complexity when transfers are large, frequent, and overlap with rendering."}, {"t": "Indirect draw (D3D12.IndirectDraw)", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#indirect-draw-d3d12indirectdraw", "x": "Indirect draw ( D3D12.IndirectDraw ) # ExecuteIndirect reads its draw parameters from a GPU buffer instead of from CPU arguments. The GPU can fill that buffer itself (via compute), so the CPU never sees the individual draws: Flow When to use: GPU-driven rendering — the GPU culls objects and builds its own draw list, so a scene with 100,000 candidate objects costs the CPU one call. This is the backbone of modern GPU-driven pipelines. When not to: if the CPU already knows the draws and there aren't many, ordinary DrawIndexedInstanced is simpler and easier to debug. Indirect draw is for massive counts or when draw parameters are computed on the GPU."}, {"t": "Geometry & tessellation, D3D12 edition", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#geometry-tessellation-d3d12-edition", "x": "# Tier2 also re-homes the geometry and tessellation stages (same gs_5_0 / hs_5_0 + ds_5_0 concepts from Parts III–IV) into the explicit D3D12 model — same shaders, now driven through PSOs and root signatures. The pipeline is unchanged; only the plumbing is explicit. That's the recurring D3D12 lesson."}, {"t": "Module 9 — Tier 3: Compute-Driven Rendering", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#module-9-tier-3-compute-driven-rendering", "x": "#"}, {"t": "The problem it solved", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#the-problem-it-solved_1", "x": "# Compute shaders (Part IV) let the GPU do general work; D3D12 lets you schedule that work explicitly — on a separate queue, overlapping graphics — and bind resources bindlessly , removing the descriptor-shuffling that limited D3D11."}, {"t": "Compute in D3D12 (D3D12.ComputeShader)", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#compute-in-d3d12-d3d12computeshader", "x": "Compute in D3D12 ( D3D12.ComputeShader ) # Same cs_5_0 / Dispatch model as D3D11, but you insert the UAV barriers that D3D11 inserted for you. The write-then-read hazard from Part IV is now an explicit D3D12_RESOURCE_BARRIER (UAV or transition) between the dispatch and the draw that samples the result. Convenience became responsibility — the through-line of the whole D3D12 story."}, {"t": "Async compute (D3D12.ComputeAsync)", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#async-compute-d3d12computeasync", "x": "Async compute ( D3D12.ComputeAsync ) # This is the payoff for having separate queues. Submit compute work to a compute queue that runs concurrently with the graphics queue, so the GPU's compute units stay busy during graphics bubbles: Flow When to use: overlapping independent workloads — e.g. run next frame's light-culling compute while this frame's shadow passes render. On GPUs with spare compute capacity during graphics-heavy phases, this is free performance. When not to: if compute and graphics both saturate the same units, running them \"concurrently\" just time-slices with extra sync overhead — you can lose performance. Async compute needs measurement ; it is not automatically a win. Decision lens — async compute. Profile first. It helps when one queue has idle units the other can use (memory-bound graphics + ALU-bound compute, or vice versa). It hurts when both fight for the same resource. The cross-queue fences also add real complexity — only adopt it if the profiler shows the gap."}, {"t": "Bindless (D3D12.Bindless)", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#bindless-d3d12bindless", "x": "Bindless ( D3D12.Bindless ) # Classic binding names each texture in the root signature — a hard limit and constant descriptor shuffling. Bindless puts all resources in one big descriptor heap and lets the shader index it with an integer (using SM5.1's unbounded arrays / dynamic indexing): HLSL Copy When to use: many materials/textures, GPU-driven rendering (the GPU picks which texture per object), ray tracing (a hit shader must reach any material). Bindless is a prerequisite for most modern GPU-driven and raytraced pipelines. When not to: a simple forward renderer with a few textures doesn't need it; traditional binding is easier to reason about. Bindless trades a little safety and clarity for enormous flexibility and scale."}, {"t": "Deferred shading / MRT (D3D12.DeferredMRT)", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#deferred-shading-mrt-d3d12deferredmrt", "x": "Deferred shading / MRT ( D3D12.DeferredMRT ) # Multiple render targets let one pixel-shader pass write several outputs at once — position, normal, albedo — into a G-buffer . A later fullscreen pass reads the G-buffer and computes lighting once per screen pixel: Flow When to use: scenes with many dynamic lights. Forward shading costs objects × lights ; deferred decouples them to objects + lights , so hundreds of lights become affordable. When not to: deferred struggles with transparency (a G-buffer stores one surface per pixel) and MSAA (expensive on a fat G-buffer), and it burns memory bandwidth on the G-buffer itself. Forward+ / clustered forward are often better for transparency-heavy or bandwidth-limited targets. Decision lens — forward vs. deferred. Deferred when light count dominates and materials are fairly uniform. Forward (or Forward+) when you have heavy transparency, need cheap MSAA, or run on bandwidth-constrained hardware. There's no universally right answer — it's a bandwidth-vs-light-count trade."}, {"t": "Historical \"why now?\"", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#historical-why-now", "x": "# Once the GPU could run general compute (D3D11) and the API stopped hiding queues, memory, and descriptors (D3D12), \"let the GPU drive itself\" became practical: cull, build draw lists, and shade — all on the GPU, with the CPU merely kicking it off. Tier 2 and Tier 3 are where D3D12 stops being \"D3D11 with more typing\" and starts enabling things D3D11 simply couldn't."}, {"t": "Part VI in one paragraph", "p": "Part VI — Feeding the GPU: Memory, Copies, and GPU-Driven Work", "u": "part-06-feeding-the-gpu.html#part-vi-in-one-paragraph", "x": "# Tier 2 exposes memory (placed resources, heap aliasing) and data movement (the parallel copy queue, GPU-authored draws via ExecuteIndirect ). Tier 3 turns the GPU into the director: async compute overlaps independent work across queues, bindless removes binding limits so shaders index resources by integer, and deferred MRT decouples lighting cost from object count. Every one of these is a when-to-use decision with a real downside — the point of D3D12 isn't that these are better, it's that you're now the one choosing."}, {"t": "Part VII — Image Quality & the Modern Pipeline", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#part-vii-image-quality-the-modern-pipeline", "x": "# Part VII · Tier 4 · SM 6 6 samples in this part ShadowMap MSAA VariableRateShading MeshShader AmplificationShader RayTracing Tier 4 covers two different frontiers at once. The first is image quality — the classic techniques that make a render look correct and clean: shadows, anti-aliasing, and adaptive shading. The second is the Shader Model 6 pipeline revolution — mesh/amplification shaders and hardware ray tracing, which redefine how geometry reaches the rasterizer and how light is simulated. Both live in D3D12\\Tier4\\ . Anchoring samples: ShadowMap , MSAA , VariableRateShading (image quality) and MeshShader , AmplificationShader , RayTracing (SM6 pipeline)."}, {"t": "Module 10a — Image Quality Fundamentals", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#module-10a-image-quality-fundamentals", "x": "#"}, {"t": "Shadow mapping (D3D12.ShadowMap)", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#shadow-mapping-d3d12shadowmap", "x": "Shadow mapping ( D3D12.ShadowMap ) # The oldest trick for real-time shadows, and still the dominant one. Render the scene from the light's point of view into a depth texture; then, when shading each pixel, transform it into light space and compare its depth against the stored depth — if it's farther, it's in shadow. Flow The sample uses a typeless depth resource so the same texture can be a DSV when written and an SRV when read, plus a comparison sampler that does the depth test in hardware (giving smooth PCF edges for free). When to use: essentially always for dynamic shadows from spot/directional lights. It's the baseline every game builds on. When not to (naively): a single shadow map has fixed resolution — great near the camera, blocky far away. Large scenes need cascaded shadow maps (several maps at different ranges), and point lights need cube maps or other tricks. Shadow mapping is a family of techniques, not one setting; the sample teaches the core so the elaborations make sense. Decision lens — shadow technique. Single map for a small, contained scene. Cascades for open worlds (resolution where it matters). Ray-traced shadows (below) when you have the hardware budget and w"}, {"t": "MSAA (D3D12.MSAA)", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#msaa-d3d12msaa", "x": "MSAA ( D3D12.MSAA ) # Multisample anti-aliasing fixes jagged geometry edges by sampling coverage and depth at multiple points per pixel while shading only once per pixel — cheaper than supersampling. In D3D12 you render to a multisampled target and then resolve it down to a normal one: Flow When to use: geometry-edge aliasing in forward-rendered scenes. 4× MSAA is a long-standing sweet spot for quality vs. cost. When not to: MSAA only anti-aliases geometry edges , not shader aliasing (specular sparkle) or texture aliasing, and it's expensive on a deferred G-buffer (Part VI). That's why many modern engines prefer post-process AA (FXAA) or temporal AA (TAA), which handle shader aliasing and cost less on deferred pipelines — at the price of some blur/ghosting. Decision lens — anti-aliasing. MSAA for forward rendering with clean edges and no ghosting. TAA for deferred/complex pipelines and shader aliasing, accepting temporal artifacts. FXAA as a cheap catch-all. Often engines combine them."}, {"t": "Variable-rate shading (D3D12.VariableRateShading)", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#variable-rate-shading-d3d12variablerateshading", "x": "Variable-rate shading ( D3D12.VariableRateShading ) # VRS lets you shade coarser than one invocation per pixel where detail won't be missed — e.g. 2×2 pixels share one shading result in blurry, distant, or motion-blurred regions. It's set on a ID3D12GraphicsCommandList5 : C Copy When to use: shading-bound scenes where you can afford to shade some regions coarsely — peripheral vision (foveated VR), out-of-focus areas, fast-moving regions hidden by motion blur. It's close to free performance when applied where the eye won't notice. When not to: if you're geometry- or bandwidth-bound rather than shading-bound, VRS buys nothing. And applied carelessly it produces visible blocky shading. It also requires hardware support (this machine reports VRS Tier 2). Measure that you're shading-bound before reaching for it."}, {"t": "Module 10b — The Shader Model 6 Pipeline Revolution", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#module-10b-the-shader-model-6-pipeline-revolution", "x": "# Everything up to here fed the rasterizer through the same fixed front end: input-assembler → vertex shader → (optional geometry/tessellation) → rasterizer. SM6 offers two radical alternatives."}, {"t": "Mesh & amplification shaders (D3D12.MeshShader, D3D12.AmplificationShader)", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#mesh-amplification-shaders-d3d12meshshader-d3d12amplificationshader", "x": "Mesh & amplification shaders ( D3D12.MeshShader , D3D12.AmplificationShader ) # The mesh shader replaces the entire input-assembler/vertex/geometry front end with a compute-style program that outputs a small batch of triangles (a \"meshlet\") directly: HLSL Copy The amplification shader runs before it and decides how many mesh-shader groups to launch — the natural place to do per-meshlet culling (skip meshlets that are off-screen or back-facing before they cost anything): Flow When to use: extremely dense geometry, GPU-driven culling at meshlet granularity, and procedural geometry — the mesh pipeline removes the fixed-function bottlenecks (index-buffer fetch, primitive assembly) that limited the classic front end. It's the modern answer to \"draw enormous amounts of geometry efficiently.\" When not to: it requires recent hardware and a mesh-friendly content pipeline (your assets must be split into meshlets). For ordinary geometry the classic vertex pipeline is simpler and universally supported. Mesh shaders are a scale-and-modernity play, not a default. Decision lens — classic vs. mesh pipeline. Classic vertex/index for broad compatibility and ordinary meshes. Mesh + amplification when"}, {"t": "Ray tracing / DXR (D3D12.RayTracing)", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#ray-tracing-dxr-d3d12raytracing", "x": "Ray tracing / DXR ( D3D12.RayTracing ) # Rasterization asks \"which pixels does this triangle cover?\" Ray tracing asks the inverse: \"what does this ray hit?\" — the natural formulation for reflections, refractions, accurate shadows, and global illumination. DXR introduces a whole sub-model: acceleration structures (BLAS/TLAS) that organize geometry for fast ray queries, and a new family of shaders: ray generation — casts primary rays, closest-hit / any-hit — shade what a ray hits, miss — what a ray hits nothing (sky). Flow This is why bindless (Part VI) matters: a hit shader may strike any object, so it must reach any material's resources by index. Ray tracing is also the payoff for everything explicit about D3D12 — the shader table, acceleration-structure memory, and barriers are all yours to manage. When to use: effects that rasterization fakes poorly — mirror-accurate reflections, soft contact shadows, ambient occlusion, and global illumination. Often used hybrid : rasterize primary visibility, ray-trace specific effects. When not to: ray tracing is expensive and needs RT-capable hardware; a fully path-traced game is still a premium feature. For many effects a well-tuned raster ap"}, {"t": "Historical \"why now?\"", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#historical-why-now", "x": "# By the late 2010s GPUs gained dedicated hardware — mesh-shader front ends and ray-traversal units (RT cores) — and the SM6 (DXIL) compiler could express these new pipelines. D3D12's explicit model was the prerequisite: managing acceleration structures, shader tables, and meshlet buffers would be impossible under D3D11's hidden bookkeeping. These features are where the pipeline itself finally changes shape after two decades of the same rasterizer front end."}, {"t": "Part VII in one paragraph", "p": "Part VII — Image Quality & the Modern Pipeline", "u": "part-07-image-quality-modern-pipeline.html#part-vii-in-one-paragraph", "x": "# Tier 4 pairs classic image quality (shadow maps for shadows, MSAA-plus-resolve for edge anti-aliasing, VRS for adaptive shading cost) with the Shader Model 6 pipeline revolution (mesh + amplification shaders that replace the fixed geometry front end with programmable, culling-aware meshlet generation, and DXR ray tracing that inverts the visibility question for accurate reflections, shadows, and GI). Each is a deliberate trade — quality vs. cost, compatibility vs. scale, raster approximation vs. ray-traced accuracy — and each depends on the explicit foundation D3D12 laid."}, {"t": "Part VIII — Recording & Querying at Scale (Tier 5)", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#part-viii-recording-querying-at-scale-tier-5", "x": "# Part VIII · Tier 5 4 samples in this part MultiThreadedRecording Bundles Queries Predication Build note. The Tier 5 samples described here now exist under D3D12\\Tier5\\ and build with build-all.ps1 . The short code sketches below are simplified for teaching; read each sample's main.c for the full, annotated implementation. D3D12's headline promise back in Part V was lower, more predictable CPU overhead and multithreaded submission . Tier 1–4 mostly stayed single-threaded to keep the teaching clear. Tier 5 finally cashes that promise: recording commands across many threads, pre-recording reusable command sequences, and letting the GPU report back what actually happened so you can make decisions from real data. Anchoring samples ( D3D12\\Tier5\\ ): MultiThreadedRecording , Bundles , Queries , Predication ."}, {"t": "Module 11 — Command Recording & GPU Feedback", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#module-11-command-recording-gpu-feedback", "x": "#"}, {"t": "Multithreaded recording (MultiThreadedRecording)", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#multithreaded-recording-multithreadedrecording", "x": "Multithreaded recording ( MultiThreadedRecording ) # This is the reason the D3D12 object model splits queue / allocator / list. Give each worker thread its own allocator and command list, record in parallel, then submit all the lists on one queue: Flow When to use: scenes with thousands of draws where a single thread can't record fast enough to keep the GPU fed. This is the payoff that justifies D3D12's whole complexity budget for large titles. When not to: small scenes gain nothing — the threading overhead and the per-thread allocator memory outweigh the benefit. And correctness is subtle: each list needs its own allocator, and you can't reset an allocator while the GPU is still consuming its commands (fences again). Decision lens — go multithreaded when the profiler says the submit thread is the bottleneck. If you're GPU-bound or draw counts are modest, single-threaded recording is simpler and just as fast. Threading is a scaling tool, not a default."}, {"t": "Bundles (Bundles)", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#bundles-bundles", "x": "Bundles ( Bundles ) # A bundle is a small, pre-recorded command list you build once and replay many times, cheaply, across frames. Unlike a full command list, a bundle inherits most state from the caller and is optimized for reuse: Flow When to use: repeated, unchanging draw sequences — the same mesh drawn every frame, UI elements, static props. Bundles shave CPU recording cost off the hot path. When not to: anything whose commands change per frame can't be a static bundle, and bundles have restrictions (limited state inheritance, no resource transitions inside). For dynamic work, record normally. Bundles are a micro-optimization that matters only when recording cost is measurable."}, {"t": "Queries (Queries)", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#queries-queries", "x": "Queries ( Queries ) # The GPU runs asynchronously, so \"how long did that pass take?\" or \"how many pixels passed the depth test?\" can't be answered by CPU timing. Query heaps let the GPU write those answers into a buffer you read back a frame or two later: Flow When to use: GPU profiling (timestamp queries for pass durations), occlusion culling (occlusion queries: did anything pass, so should I bother drawing the detailed version?), and pipeline-statistics for understanding vertex/pixel counts. Real data beats guessing. When not to: queries add synchronization and readback latency; sprinkling them everywhere hurts. Use them deliberately for profiling or a specific culling decision, and always read results latently (never stall the GPU waiting for a query this frame)."}, {"t": "Predication (Predication)", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#predication-predication", "x": "Predication ( Predication ) # Predication lets the GPU skip commands based on a value in a buffer — without a CPU round-trip. Pair it with an occlusion query: draw a cheap bounding box, and predicate the expensive draw on whether the box was visible: Flow When to use: GPU-driven culling where you want the GPU to decide whether to execute work, avoiding the latency of reading a query back to the CPU and re-submitting. It keeps culling decisions on-GPU and pipelined. When not to: if the CPU already knows visibility, cull on the CPU and don't submit the draw at all — that's strictly cheaper than submitting a predicated draw. Predication earns its keep specifically when the deciding data lives on the GPU. Decision lens — where does the cull decision live? CPU-side cull when the CPU has the data (don't submit at all). GPU-side predication/indirect when the visibility data is produced on the GPU and a CPU round-trip would cost more than it saves."}, {"t": "Historical \"why now?\"", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#historical-why-now", "x": "# These aren't new capabilities so much as the maturation of D3D12's model. Once command recording is explicit and multithreaded, bundles and multithreaded recording are the obvious tools to exploit it; once the GPU is fully asynchronous, queries and predication are how you observe and steer it without dragging work back to the CPU. Tier 5 is D3D12 used the way it was designed to be used."}, {"t": "Part VIII in one paragraph", "p": "Part VIII — Recording & Querying at Scale (Tier 5)", "u": "part-08-recording-querying-at-scale.html#part-viii-in-one-paragraph", "x": "# Tier 5 delivers on D3D12's original promise: multithreaded recording (each thread its own allocator/list, one submit) scales draw submission across cores; bundles pre-record reusable sequences to cut hot-path CPU cost; queries let the asynchronous GPU report timing, occlusion, and statistics back to you; and predication keeps culling decisions on the GPU when that's where the data lives. The unifying theme is scale and feedback — using the explicit model deliberately, guided by measurement rather than assumption."}, {"t": "Part IX — Classic Pipeline Mastery (Tier 6)", "p": "Part IX — Classic Pipeline Mastery (Tier 6)", "u": "part-09-classic-pipeline-mastery.html#part-ix-classic-pipeline-mastery-tier-6", "x": "# Part IX · Tier 6 3 samples in this part Instancing Blending Stencil Build note. The Tier 6 samples described here now exist under D3D12\\Tier6\\ and build with build-all.ps1 . Code sketches below are simplified for teaching; read each sample's main.c for the full version. The exotic features (mesh shaders, ray tracing) get the attention, but shipping games spend most frames on three humble techniques that every renderer needs and that beginners routinely get subtly wrong: instancing , blending , and stencil . Tier 6 slows down on these fundamentals — done in the explicit D3D12 model — because mastering them separates a renderer that works from one that looks correct . Anchoring samples ( D3D12\\Tier6\\ ): Instancing , Blending , Stencil ."}, {"t": "Module 12 — Fundamentals That Ship Every Game", "p": "Part IX — Classic Pipeline Mastery (Tier 6)", "u": "part-09-classic-pipeline-mastery.html#module-12-fundamentals-that-ship-every-game", "x": "#"}, {"t": "Instancing (Instancing)", "p": "Part IX — Classic Pipeline Mastery (Tier 6)", "u": "part-09-classic-pipeline-mastery.html#instancing-instancing", "x": "Instancing ( Instancing ) # Draw the same mesh many times in one call, with per-instance data (transform, color) pulled from a second vertex stream or a buffer indexed by SV_InstanceID : HLSL Copy Flow When to use: forests, crowds, particles, debris, grass — anything with many copies of one mesh. Instancing collapses thousands of draws into one, slashing CPU overhead. It's the single most important draw-call optimization. When not to: if every object is a different mesh, instancing doesn't apply (look at indirect draw / GPU-driven instead). And extreme instance counts of complex meshes can become GPU-bound — instancing fixes CPU cost, not GPU cost. Decision lens — reducing draw calls. Instancing for many copies of one mesh. Merged/static batching for many static different meshes. Indirect draw (Part VI) when the GPU decides counts. Pick by what varies between your objects."}, {"t": "Blending (Blending)", "p": "Part IX — Classic Pipeline Mastery (Tier 6)", "u": "part-09-classic-pipeline-mastery.html#blending-blending", "x": "Blending ( Blending ) # Blending combines a fragment's output with what's already in the render target — the basis of transparency, glass, smoke, and UI compositing: Flow The catch that trips everyone: order . Alpha blending is not commutative, so transparent surfaces must be drawn back-to-front , and depth writes usually disabled for them (depth test still on). Additive blending (for fire, glow) is order-independent, which is part of why it's popular. When to use: any translucency — windows, water surfaces, particles, UI. Bake the blend state into the PSO for the transparent pass. When not to (carelessly): don't blend opaque geometry (it's wasteful and order-dependent); render opaques first with depth writes on, then transparents sorted. And heavy overdraw from many blended layers is a common, silent performance sink. Decision lens — transparency strategy. Sorted back-to-front alpha for general translucency (accept the sort cost). Additive for glows/particles (order-free). Order-independent transparency (OIT) techniques only when sorting genuinely can't produce a correct order and you can afford the extra passes."}, {"t": "Stencil (Stencil)", "p": "Part IX — Classic Pipeline Mastery (Tier 6)", "u": "part-09-classic-pipeline-mastery.html#stencil-stencil", "x": "Stencil ( Stencil ) # The stencil buffer is a small per-pixel integer you write and test alongside depth — a general-purpose \"mask\" for the screen. Write a value in one pass, then restrict a later pass to only the pixels carrying that value: Flow When to use: mirrors and portals (mask drawing to a region), decals, outline effects, constructive masking, and clever multi-pass tricks. Stencil is cheap (it rides along with the depth buffer) and remarkably versatile. When not to: for simple rectangular clipping a scissor rect is simpler; for complex compositing a compute pass may be clearer. Stencil shines for geometry-defined masks resolved during rasterization. Decision lens — masking a region. Scissor rect for axis-aligned rectangles. Stencil for arbitrary geometry-shaped masks resolved in the raster pipeline. Compute/UAV for programmatic masks you compute yourself."}, {"t": "Historical \"why now?\" (in the course, not in the API)", "p": "Part IX — Classic Pipeline Mastery (Tier 6)", "u": "part-09-classic-pipeline-mastery.html#historical-why-now-in-the-course-not-in-the-api", "x": "# These features are as old as the fixed-function era — D3D7 had blending and stencil. They appear here in the course, not because they're new, but because seeing them in the explicit D3D12 model (baked into PSOs, sequenced with barriers, driven with instanced/indirect draws) ties the fundamentals to everything the modern API added. Mastery is knowing that the newest GPU still lives or dies by how well you sort your transparents."}, {"t": "Part IX in one paragraph", "p": "Part IX — Classic Pipeline Mastery (Tier 6)", "u": "part-09-classic-pipeline-mastery.html#part-ix-in-one-paragraph", "x": "# Tier 6 returns to the fundamentals every renderer ships: instancing (one call, thousands of copies — the top draw-call optimization), blending (translucency, with the ever-present ordering and overdraw caveats), and stencil (a per-pixel geometry mask for mirrors, decals, and outlines). None are new to D3D12, but seeing them in the explicit model — baked into PSOs, ordered deliberately — is what turns a renderer that runs into one that looks correct."}, {"t": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#part-x-presentation-devices-advanced-resources-tiers-78", "x": "# Part X · Tier 7 · Tier 8 5 samples in this part HDR MultiAdapter PipelineLibraries ReservedResources Debugging Build note. The Tier 7 and Tier 8 samples described here now exist under D3D12\\Tier7\\ and D3D12\\Tier8\\ and build with build-all.ps1 . Code sketches below are simplified for teaching; read each sample's main.c for the full implementation and its capability-fallback paths. The final two \"classic-D3D12\" tiers deal with the edges of the system: how frames reach a real (possibly HDR, possibly multi-GPU) display, how to manage resources too big to fit in memory, and how to keep the whole explicit machine correct during development. These are the topics that separate a sample from a shippable product. Anchoring samples: Tier 7 ( D3D12\\Tier7\\ ) — HDR , MultiAdapter ; Tier 8 ( D3D12\\Tier8\\ ) — PipelineLibraries , ReservedResources , Debugging ."}, {"t": "Module 13 — Tier 7: Getting Frames to the Display", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#module-13-tier-7-getting-frames-to-the-display", "x": "#"}, {"t": "HDR output (HDR)", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#hdr-output-hdr", "x": "HDR output ( HDR ) # Standard rendering targets an 8-bit SDR display. HDR output presents in a wide-gamut, high-dynamic-range format (e.g. R10G10B10A2 with the HDR10 color space, or R16G16B16A16_FLOAT with scRGB) so bright highlights and deep colors survive to a capable monitor: Flow When to use: when you want your carefully lit, physically-based scene to look right on HDR TVs and monitors — the bright sun, glinting metal, and dark shadows that SDR crushes. Requires querying the display's actual capabilities and tone-mapping to them. When not to: HDR adds real pipeline and testing complexity (you must handle SDR and HDR paths, and tone-mapping is easy to get wrong). If your art is authored for SDR and your audience is mostly SDR, it may not be worth it. HDR is a quality investment, not a checkbox."}, {"t": "Multi-adapter (MultiAdapter)", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#multi-adapter-multiadapter", "x": "Multi-adapter ( MultiAdapter ) # Some systems have more than one GPU — an integrated + discrete pair, or multiple discrete cards. D3D12 exposes each adapter explicitly and lets you split work across them: Flow When to use: rare, specialized cases — offloading post to the iGPU, professional multi-GPU rendering, or explicit alternate-frame setups. When it fits, it's free hardware. When not to: for almost all games. Cross-adapter synchronization and data transfer are complex and fragile, driver support varies, and the classic SLI/CF alternate-frame model has largely faded. Treat multi-adapter as a niche tool, not a scaling strategy. Decision lens — presentation & devices. Add HDR when your lighting is HDR-authored and the audience has the displays. Reach for multi-adapter only for a concrete, measured offload; otherwise target one adapter and keep the engine simple."}, {"t": "Module 14 — Tier 8: Big Resources & Staying Correct", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#module-14-tier-8-big-resources-staying-correct", "x": "#"}, {"t": "Pipeline libraries (PipelineLibraries)", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#pipeline-libraries-pipelinelibraries", "x": "Pipeline libraries ( PipelineLibraries ) # Recall the PSO explosion from Part V: every shader × state combination is a separate object, and each is expensive to compile. Pipeline libraries let you cache compiled PSOs to disk and reload them next run, skipping recompilation: Flow When to use: any real game with many PSOs and long shader-compile times. Caching turns a multi-second (or multi-minute) first-run compile into an instant warm start, and helps eliminate the in-game hitches of compiling PSOs on demand. When not to: a tiny app with two PSOs doesn't need the machinery. Also, the cache is driver/hardware-specific and must be invalidated when drivers change — manage it, don't blindly trust it."}, {"t": "Reserved (tiled) resources (ReservedResources)", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#reserved-tiled-resources-reservedresources", "x": "Reserved (tiled) resources ( ReservedResources ) # A reserved resource has a virtual address range but no physical memory until you map tiles into it on demand — the D3D12 mechanism behind megatextures and sparse virtual texturing: Flow When to use: resources far larger than VRAM where only a fraction is needed at once — virtual texturing, sparse voxel volumes, streaming terrain. It's the way to have a \"16K texture\" without paying 1 GB. When not to: ordinary textures that fit in memory — reserved resources add significant management complexity (tile pools, mapping, residency) for no benefit unless you're genuinely memory-constrained at huge scale. Decision lens — resource residency. Committed/placed for things that fit. Reserved/tiled only when the resource is bigger than memory and naturally sparse. The complexity is only worth it at extreme scale."}, {"t": "Debugging (Debugging)", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#debugging-debugging", "x": "Debugging ( Debugging ) # D3D12 took away the driver's safety net (Part V), so you must catch the errors it used to prevent. The tooling that makes explicit D3D12 survivable: the debug layer ( ID3D12Debug ) — validates every call, catches bad barriers, wrong states, and resource misuse; GPU-based validation — deeper checks that run on the GPU; DRED (Device Removed Extended Data) — post-mortem info when the GPU hangs or is removed; PIX markers — named regions for the profiler/debugger. DirectX dump files (preview) — full GPU crash dumps, see below. C Copy When to use: always , during development. The debug layer will tell you exactly which barrier is wrong or which resource is in the wrong state — the class of bug that otherwise shows up as random corruption or a hang on someone else's GPU. When not to: ship with it off (it's slow). But developing D3D12 without the debug layer is choosing to debug blind — don't. Decision lens — this one's not a trade-off. Enable the debug layer and validation in every development build. The only \"when not to\" is the shipping build, for performance. Explicit APIs make validation tooling essential, not optional. What's next after DRED: DirectX dump fi"}, {"t": "Historical \"why now?\"", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#historical-why-now", "x": "# Tiers 7–8 are the production-hardening layer: the features you need once a D3D12 renderer stops being a demo and has to run on real users' varied displays and GPUs, load quickly, stream huge assets, and be debuggable when it breaks. They close the loop on explicitness — having taken the driver's help away, D3D12 gives you the tools (pipeline caches, validation, DRED) to live without it."}, {"t": "Part X in one paragraph", "p": "Part X — Presentation, Devices & Advanced Resources (Tiers 7–8)", "u": "part-10-presentation-devices-resources.html#part-x-in-one-paragraph", "x": "# Tier 7 gets frames onto real hardware: HDR presentation for wide-gamut displays and multi-adapter for the rare multi-GPU offload. Tier 8 hardens the engine: pipeline libraries cache compiled PSOs to kill first-run compile hitches, reserved/tiled resources give virtually-huge sparse textures without the memory, and the debug layer + validation + DRED replace the safety net D3D12 removed. Together they mark the transition from \"it renders\" to \"it ships\" — and they exist precisely because explicitness demanded them."}, {"t": "Part XI — The Frontier: Where Direct3D Is Heading", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#part-xi-the-frontier-where-direct3d-is-heading", "x": "# Part XI · Tier 9 · Agility SDK 9 samples in this part No live capture Root-signature creation failed on the capture machine's driver - see the sample's .log. SamplerFeedback DynamicResources WorkGraphs EnhancedBarriers No live capture DirectStorage factory creation returned E_NOTIMPL on the capture machine - see the sample's .log. DirectStorage RayTracing12 LinearAlgebra PartialPrograms RayTracing Roadmap note. These are Agility SDK frontier features — the newest additions, delivered out-of-band from Windows via the D3D12 Agility SDK. Build note. These samples live under D3D12\\Tier9\\ ( D3D12.SamplerFeedback , D3D12.DynamicResources , D3D12.WorkGraphs , D3D12.EnhancedBarriers , D3D12.DirectStorage , D3D12.RayTracing12 , D3D12.LinearAlgebra , D3D12.PartialPrograms ). The first five build against the Windows 10.0.26100 SDK (DirectStorage vendors its NuGet SDK locally). The last three are preview samples: each vendors the Agility SDK 1.721-preview, the preview DXC and the preview WARP software rasterizer via its own fetch-deps.ps1 . Every sample queries its capability tier at runtime. The preview samples try the GPU first and, when the driver doesn't expose the feature yet, re-run on"}, {"t": "Module 15 — The Agility-SDK Frontier", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#module-15-the-agility-sdk-frontier", "x": "#"}, {"t": "SM6.6 dynamic resources / ResourceDescriptorHeap", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#sm66-dynamic-resources-resourcedescriptorheap", "x": "# Bindless (Part VI) still needed you to declare descriptor tables. Shader Model 6.6 dynamic resources go further: shaders index the descriptor heap directly by integer, with no root-signature table at all: HLSL Copy When to use: fully GPU-driven and ray-traced pipelines where \"any shader reaches any resource by index\" is the natural model. It's the cleanest, most flexible binding model D3D12 has offered — the logical end of the road that started with descriptor heaps in Part V. When not to: it requires SM6.6-capable hardware/drivers, and the total lack of binding declarations makes mistakes harder to catch. Simpler renderers don't need it. It's the tool for large, dynamic, GPU-driven resource sets."}, {"t": "Enhanced barriers", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#enhanced-barriers", "x": "# The original ResourceBarrier model (Part V) is coarse — it conflates several kinds of synchronization and is easy to over-sync. Enhanced barriers split the concept into precise layout , sync , and access dimensions: Flow When to use: performance-critical engines that were leaving GPU cycles on the table with the old coarse barriers. Enhanced barriers let you express exactly the synchronization you need and no more — fewer stalls, less cache flushing. When not to: the legacy barriers still work and are simpler to reason about. Enhanced barriers are an optimization for teams profiling barrier overhead — not a required migration. Decision lens — barrier model. Legacy ResourceBarrier for clarity and broad support. Enhanced barriers when the profiler shows you're over-syncing and you want fine control. Same correctness goal, finer instrument."}, {"t": "Sampler feedback", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#sampler-feedback", "x": "# Sampler feedback lets the GPU record which parts of a texture (which mip tiles) were actually sampled while shading. Feed that map back into your streaming system to load exactly the texture data the frame needed — no more, no less: Flow When to use: texture-streaming and virtual-texturing systems (pairs naturally with reserved resources, Part X). It replaces heuristics (\"guess what's visible\") with ground truth (\"here's what was sampled\"), cutting memory waste dramatically. When not to: if you're not streaming textures, there's nothing to feed back. It's a specialized tool for large-world streaming, not a general feature."}, {"t": "Work graphs", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#work-graphs", "x": "# Perhaps the most forward-looking feature. Work graphs let the GPU generate and schedule its own work — nodes that launch other nodes — without round-trips to the CPU. It generalizes indirect draw and DispatchMesh into a full on-GPU task graph: Flow When to use: highly dynamic, data-dependent GPU pipelines where the amount and kind of work is decided on the GPU — advanced culling, procedural generation, GPU-driven everything. It's the frontier of \"the GPU drives itself.\" When not to: it's new, hardware/driver support is still spreading, and it's overkill for pipelines with a fixed, CPU-known structure. Today it's for engine R&D and cutting-edge titles, not mainstream adoption."}, {"t": "DirectStorage", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#directstorage", "x": "# Not a rendering feature — an I/O one, but transformative. DirectStorage streams assets from NVMe SSDs to GPU memory with minimal CPU involvement and GPU decompression , bypassing the traditional slow, CPU-heavy load path: Flow When to use: fast level loading and seamless open-world streaming — the tech behind \"instant\" loads on modern consoles and PCs. It attacks the load-time and streaming bottleneck that VRAM size and CPU decompression created. When not to: small games with tiny assets won't notice. Its benefits scale with asset size and streaming intensity; it needs an NVMe SSD to shine."}, {"t": "Ray tracing, second generation: DXR 1.2 (D3D12.RayTracing12)", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#ray-tracing-second-generation-dxr-12-d3d12raytracing12", "x": "Ray tracing, second generation: DXR 1.2 ( D3D12.RayTracing12 ) # Part VII's D3D12.RayTracing cube is DXR 1.0: trace a ray, run the hit shader. Real scenes expose two costs that the cube hides, and DXR 1.2 (shipped with Shader Model 6.9 ) attacks both. Cost 1 — alpha-tested geometry. Foliage, fences and chain-link are triangles whose texture says \"this part is a hole.\" In DXR 1.0 the traversal hardware can't know that, so every candidate hit on such a triangle launches an any-hit shader — a full shader invocation just to sample a texture and answer \"keep going.\" Opacity micromaps (OMM) bake that answer into the acceleration structure: each triangle is subdivided into micro-triangles, each marked opaque , transparent or (in the 4-state format) unknown . The traversal hardware resolves the opaque and transparent ones by itself; the any-hit shader only runs for the \"unknown\" slivers along the edges. Flow Cost 2 — divergence. A wave runs 32–64 threads in lockstep. After a bounce, neighbouring rays hit different materials, so the wave executes every material's hit shader in turn with most lanes idle. Shader Execution Reordering (SER) splits TraceRay into steps: find the hit, let the GPU "}, {"t": "Linear algebra / neural rendering (Shader Model 6.10 preview)", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#linear-algebra-neural-rendering-shader-model-610-preview", "x": "# The newest frontier is the one that ties graphics to the ML era. Shader Model 6.10 adds a unified LinAlg Matrix API ( #include <dx/linalg.h> , dx::linalg ) that surfaces the GPU's dedicated matrix hardware — the same tensor units that power ML — directly to HLSL. It subsumes the earlier Cooperative Vectors and WaveMMA previews into three matrix scopes : Flow When to use: neural rendering — replacing a hand-written physically-based computation (lighting, denoising, upscaling, material evaluation) with a small trained neural network evaluated inside the shader, per pixel, in real time. Thread-scope matrices make this an incremental drop-in: run inference on a tiny MLP from a pixel shader thread and let the compiler map it to the matrix accelerators. Wave and thread-group scopes target heavier ML/image-processing and LLM-style GEMMs where you want big matrix throughput without hand-tiling for every GPU. Why thread-group scope matters: the inputs/weights in LLM-like networks exceed wave-matrix size limits, so a wave-scope solution forces manual tiling and a different kernel per architecture. A thread-group matrix hands the tiling decision to the driver , so you ship one implementatio"}, {"t": "Partial graphics programs & Advanced Shader Delivery (D3D12.PartialPrograms)", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#partial-graphics-programs-advanced-shader-delivery-d3d12partialprograms", "x": "Partial graphics programs & Advanced Shader Delivery ( D3D12.PartialPrograms ) # Part V's PSOs bake all state into one object, which is why they're fast to bind and slow to create. Multiply shaders by blend modes, render-target formats, vertex layouts and material options and a big game ends up with tens of thousands of PSOs. Every one is a full compile for your exact GPU and driver. There are three bad places to pay for that: a long \"compiling shaders\" screen on first launch, stutter when a PSO is first needed mid-game, or both. Pipeline libraries (Part X) help from the second run on; the first run still pays. Consoles never had this problem: the GPU is fixed, so shaders are compiled to final machine code at build time and shipped in the package. Advanced Shader Delivery (ASD) brings that model to PC. The store compiles a game's shaders ahead of time for specific GPU + driver combinations and delivers them with the download, so the first launch doesn't compile at all. It first shipped for the ROG Xbox Ally handhelds. ASD only scales if the number of things to precompile is manageable, and that is what partial graphics programs (Agility SDK 1.721-preview) address. Pipeline creation"}, {"t": "Also on the frontier (no sample)", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#also-on-the-frontier-no-sample", "x": "# Not everything in the Agility SDK is a rendering technique. These matter, but a spinning cube can't usefully demonstrate them: UAVs of depth (1.721-preview) — create unordered-access views of depth/stencil resources so compute shaders can read and write depth and stencil directly. GUID texture layouts (1.721-preview) — name an exact memory layout (e.g. row-major NV12) by GUID so CPU, camera and video blocks can share textures without swizzle copies. D3D12 video encode — steady additions (HEVC reference-list extensions, multi-pass lower-resolution encoding, rate-control statistics). This matters for streaming and capture, but it's outside a rendering course. Application-specific driver state — a tools API ( ID3D12Tools2::SetApplicationSpecificDriverState ) that lets capture/replay tools such as PIX save the driver's per-app state and restore it, so a replay behaves like the original run. DirectX dump files — console-style GPU crash dumps on Windows; covered with debugging in Part X . Decision lens — the frontier in general. These features share a profile: big wins at scale , real hardware/driver requirements, and added complexity. Adopt them when you've hit the specific wall they "}, {"t": "Historical \"why now?\"", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#historical-why-now", "x": "# The Agility SDK exists because tying graphics features to OS releases was too slow. The features themselves all push the same direction the whole course has traced: more of the decision-making moves onto the GPU , and the CPU's role shrinks toward \"start the GPU and get out of the way.\" Dynamic resources, work graphs, and DirectStorage are what a fully GPU-driven, self-scheduling, self-streaming renderer is built from. With SER , the GPU even reorders its own threads. With SM6.10 linear algebra it runs neural networks inline, folding the ML era directly into the shader. Meanwhile partial programs and Advanced Shader Delivery borrow the console's oldest advantage, shipping compiled shaders instead of compiling them on the player's machine."}, {"t": "Part XI in one paragraph", "p": "Part XI — The Frontier: Where Direct3D Is Heading", "u": "part-11-the-frontier.html#part-xi-in-one-paragraph", "x": "# The Agility-SDK frontier continues D3D12's trajectory toward GPU autonomy: SM6.6 dynamic resources finish the bindless journey (index the heap directly, no tables); enhanced barriers give precise, low-waste synchronization; sampler feedback replaces streaming guesswork with ground truth; work graphs let the GPU generate and schedule its own work without the CPU; DirectStorage streams and decompresses assets straight to the GPU; DXR 1.2 resolves alpha tests inside traversal (opacity micromaps) and lets the GPU regroup divergent rays (SER); SM6.10 linear algebra runs, and now accumulates into, neural networks inline; and partial programs make precompiled, deliverable shaders (ASD) practical. Each is a scale-driven, hardware-gated tool — adopt it when you hit the specific wall it removes."}, {"t": "Part XII — Synthesis: Seeing the Whole Arc", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#part-xii-synthesis-seeing-the-whole-arc", "x": "# Part XII · The whole arc We've walked twenty-plus years and six major versions one rotating cube at a time. This closing Part steps back from any single API and looks at the shape of the whole story — the forces that drove it, the pattern that repeats, and where the line points next. If you remember nothing else, remember this Part."}, {"t": "Module 16 — The Arc in One Picture", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#module-16-the-arc-in-one-picture", "x": "# D3D7 1999 D3D8 2000 D3D9 2002 D3D10 2006 D3D11 2009 D3D12 2015 Agility 2020 Frontier 2026 Trend 1 · Programmability — what the GPU computes Trend 2 · Explicitness — who does the bookkeeping Shaders can express anything → the bottleneck moves to the CPU The two trends from Part XII : D3D7→D3D11 is the story of programmability; D3D11→D3D12→frontier is the story of explicitness. Hold the cube constant and watch what changed. Two independent trends run the entire length of the timeline: Trend 1 — Programmability (what the GPU computes). This trend ran hard from D3D7 to D3D11, then essentially finished . Era The unit of \"what runs on the GPU\" D3D7 Nothing programmable — you set render states and the fixed pipeline obeyed. D3D8 First vertex/pixel shaders (assembly) — a crack in the fixed function. D3D9 HLSL shaders ( vs_3_0 / ps_3_0 ) — programmable shading goes mainstream. D3D10 Unified shader model, geometry shader , constant buffers, views. D3D11 Compute shader + tessellation — the GPU becomes a general parallel processor. Trend 2 — Explicitness (who does the bookkeeping). This trend barely moved for a decade, then dominated everything from D3D12 on. Era Who tracks state, memory, sy"}, {"t": "Module 17 — Cross-Era Retrospective & Where It's Heading", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#module-17-cross-era-retrospective-where-its-heading", "x": "#"}, {"t": "The pattern that repeats", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#the-pattern-that-repeats", "x": "# Every major D3D transition follows the same three-beat rhythm: A hardware capability appears (programmable shaders, unified cores, compute units, RT cores, DMA/NVMe). The API exposes it , usually by removing an abstraction that used to hide it (fixed function → shaders; driver-managed state → explicit barriers; fixed geometry front end → mesh shaders). A new class of technique becomes practical (per-pixel lighting; GPU-driven rendering; ray tracing; virtual texturing). Recognizing this rhythm makes new APIs unsurprising: ask \"what hardware showed up, what abstraction is being removed, and what does that make newly possible?\""}, {"t": "The through-line: abstraction is a loan", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#the-through-line-abstraction-is-a-loan", "x": "# For twenty years the driver lent you convenience — automatic memory, synchronization, and state tracking. D3D12 called the loan. Everything explicit about D3D12 is convenience being paid back in exchange for control and predictability. That's why the honest default is still \"use the highest-level API that meets your needs.\" D3D11 is not obsolete; it's the right choice whenever you don't need to pay D3D12's price. Newer is not better — matched to the problem is better."}, {"t": "Where the line points", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#where-the-line-points", "x": "# Extend both trends and the destination is clear. Trend 1 (programmability) is essentially complete — shaders can express anything. Trend 2 (explicitness) is still moving, and its logical endpoint is GPU autonomy : the GPU generates its own work (work graphs), reaches any resource by index (dynamic resources), streams and decompresses its own assets (DirectStorage), reorders its own threads for coherence (SER), and synchronizes itself with minimal, precise barriers. The CPU's job shrinks toward \"kick off the GPU and stay out of the way.\" A second line runs alongside it: PC is adopting the console model. Consoles always had fixed hardware, precompiled shaders and GPU crash dumps. The newest Agility SDK work closes those gaps on PC: partial programs make pipelines cheap to precompile, Advanced Shader Delivery ships the compiled shaders with the download, and DirectX dump files give Windows console-style crash dumps. The next cube you render won't look different. The interesting question, as always, will be who did the work to get it there — and increasingly, the answer is the GPU itself."}, {"t": "How to keep learning", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#how-to-keep-learning", "x": "# Hold a variable constant. When you meet a new API or extension, port something you already understand (a cube, a lit sphere) and diff the code. The delta is the lesson. Always ask \"when and why,\" not just \"how.\" Every feature in this course had a \"when not to use it.\" A feature you can't say no to is a feature you don't understand yet. Follow the hardware. API features are downstream of silicon. New GPU capabilities predict the next API move."}, {"t": "The course in three sentences", "p": "Part XII — Synthesis: Seeing the Whole Arc", "u": "part-12-synthesis.html#the-course-in-three-sentences", "x": "# Direct3D's history is two trends: making the GPU programmable (D3D7→D3D11, now essentially done) and making the API explicit (D3D12→frontier, still unfolding toward GPU self-direction). Every transition removed an abstraction to expose new hardware, enabling a new class of technique — and every feature is a trade , right only when matched to a real need. The rotating cube never changed; learning to read the code around it is learning graphics."}, {"t": "Appendices", "p": "Appendices", "u": "appendices.html#appendices", "x": "# Appendices · Reference 4 samples in this part Fundamentals RayTracing12 LinearAlgebra PartialPrograms Reference material to support the main lectures: how to build and run the samples, a glossary, the \"same concept, many names\" terminology map, and where to go next."}, {"t": "Appendix A — Build & Run Cheat-Sheet", "p": "Appendices", "u": "appendices.html#appendix-a-build-run-cheat-sheet", "x": "# All samples build with a stock Visual Studio + Windows SDK toolchain on x64. The driver script build-all.ps1 at the repo root imports the VC x64 environment and invokes cl.exe directly (more reliable on shared machines than cmd /c build.bat ). Build everything: PowerShell Copy Build one sample (pass the leaf folder name — it's found at any depth): PowerShell Copy Or do everything at once: setup.ps1 checks the toolchain, fetches the preview SDKs, builds every sample (plus the 32-bit D3D7/D3D8 copies) and enables the HTML book's Run sample buttons: PowerShell Copy Where output goes. Each sample builds into its own Out\\ subfolder (e.g. D3D12\\Tier1\\D3D12.Fundamentals\\Out\\CubeD3D12.Fundamentals.exe ). Out\\ is .gitignore d so build products never clutter the tree. Run the .exe from that folder. Notes & gotchas. - The D3D12 samples compile as C ( /Tc , COBJMACROS ), so COM calls read ID3D12X_Method(obj, ...) . The era cubes (D3D7–D3D11) are C++ ( /EHsc ). - Complex D3D12 samples write a log file ( Cube<Sample>.log ) next to the exe for debugging instead of popping message boxes — read it if a sample exits unexpectedly. - D3D7 / D3D8 build as x64 but the legacy runtimes they need only sh"}, {"t": "Appendix B — Glossary", "p": "Appendices", "u": "appendices.html#appendix-b-glossary", "x": "# Terms in the order you meet them in the course. Fixed-function pipeline — a GPU with configurable but non-programmable stages; you set render states , not code (D3D7). Render state — a knob ( SetRenderState ) toggling fixed-function behavior: lighting on/off, blend mode, cull mode. FVF (Flexible Vertex Format) — a bitmask describing what's in each vertex (position, normal, color, UV) in the fixed-function era. Shader — a program that runs on the GPU for each vertex, pixel, etc. Vertex / Pixel (Fragment) shader — programs that transform vertices and color pixels. HLSL — High-Level Shading Language; the C-like language shaders are written in from D3D9 on. Shader Model (SM) — a version number for shader capability ( vs_3_0 , cs_5_0 , SM6.6). Geometry shader — an optional stage that can create/destroy primitives. Tessellation (hull/domain shader) — stages that subdivide geometry on the GPU. Compute shader / DirectCompute — general parallel GPU programs outside the draw pipeline; launched with Dispatch . Constant buffer (cbuffer / CBV) — a block of shader constants (e.g. the MVP matrix), introduced as a first-class object in D3D10. View (RTV/DSV/SRV/UAV/CBV) — a typed interpretation o"}, {"t": "Appendix C — Same Concept, Many Names", "p": "Appendices", "u": "appendices.html#appendix-c-same-concept-many-names", "x": "# The same underlying idea acquired different names as the API evolved. This table is the \"Rosetta Stone\" for reading code across eras. Concept D3D7 (fixed) D3D9 D3D10/11 D3D12 Per-draw transform data SetTransform(WORLD/VIEW/PROJ) shader constants ( SetVertexShaderConstantF ) constant buffer (cbuffer/CBV) root constants or CBV Describe vertex layout FVF bitmask FVF or vertex declaration input layout (validated vs. shader) input layout in the PSO Configure pipeline state many SetRenderState calls render states + shaders state objects set piecemeal one immutable PSO \"The GPU\" you talk to IDirect3DDevice7 IDirect3DDevice9 device + context device + queue + command list Present a frame manual Blt of a surface Present DXGI swap chain Present DXGI swap chain Present (+ barriers) A texture the shader reads texture stage texture sampler SRV SRV in a descriptor heap Who tracks resource state the driver the driver the driver you (resource barriers) Who syncs CPU/GPU the driver the driver the driver you (fences) Reading left-to-right across a row is the evolution of that concept — usually from \"the driver hides it\" toward \"you state it explicitly.\""}, {"t": "Appendix D — Further Reading", "p": "Appendices", "u": "appendices.html#appendix-d-further-reading", "x": "# Microsoft Direct3D 12 programming guide (learn.microsoft.com) — the authoritative reference for the D3D12 object model, barriers, and PSOs. DirectX-Graphics-Samples (github.com/microsoft/DirectX-Graphics-Samples) — Microsoft's official D3D12 samples; the canonical, production-grade counterparts to this course's teaching samples. DirectX Developer Blog — announcements and deep dives on Agility-SDK features (mesh shaders, DXR, work graphs, DirectStorage, enhanced barriers). \"Introduction to 3D Game Programming with DirectX\" (Frank Luna) — a thorough, book-length treatment of D3D11/12 fundamentals. The samples in this repository — the best next step is to open a sample from the tier you're studying, read it top to bottom, then change one thing and rebuild. Hold a variable constant and diff; the delta is the lesson. Return to the Syllabus » ."}, {"t": "Sample Reference", "p": "Sample reference", "u": "reference.html#sample-reference", "x": "# Supporting reference for the sample set behind The Evolution of Direct3D course. The course is the main text; this file is the catalog of the programs it teaches from — the build matrix, the per-sample tables, and the build/runtime mechanics. Every sample is a single-file Win32 app that spins a colored cube. Press ESC (or close the window) to quit any of them."}, {"t": "Build status (Windows SDK 10.0.26100, VS 2022/x64)", "p": "Sample reference", "u": "reference.html#build-status-windows-sdk-10026100-vs-2022x64", "x": "# Version Pipeline Builds Notes D3D7 DirectDraw7 + D3D7, fixed-function ✅ Windowed via a DirectDraw clipper + back-buffer blit. D3D8 IDirect3D8, fixed-function ✅ SDK dropped d3d8.h ; uses vendored Wine headers (see below). D3D9 IDirect3D9, fixed-function ✅ d3d9.h ships in the SDK shared/ folder. D3D10 Device + swap chain, HLSL ✅ Shaders compiled at runtime with D3DCompile . D3D11 Device/context + swap chain, HLSL ✅ D3D12 Queue + swap chain, root constants ✅ Minimal single-threaded fence sync; MVP via 32-bit root constants. All six compile and link with the stock Visual Studio 2022 toolchain and the Windows 10/11 SDK — no legacy DirectX SDK required. Matrices come from DirectXMath ( DirectXMath.h ), which every SDK ships."}, {"t": "Shader showcase samples (D3D9–D3D12)", "p": "Sample reference", "u": "reference.html#shader-showcase-samples-d3d9d3d12", "x": "# Alongside the six base games there are focused samples that each highlight one programmable shader stage while keeping the rotating-cube theme. Every sample is a single-file Win32 app that compiles its HLSL at runtime; folders are named <Version>.<ShaderStage> . Organization. Each base cube now lives in a <Version>.Basic folder (e.g. D3D7.Basic , D3D12\\Tier1\\D3D12.Basic ). The D3D9/D3D10/D3D11 base cubes and their shader-stage samples are grouped under per-version parent folders — D3D9\\ , D3D10\\ , D3D11\\ — while D3D12 is organized by tier under D3D12\\ . Build scripts discover samples at any depth, so the folder nesting doesn't change how you build. Folder Stage What it shows D3D9.VertexShader vs_3_0 Vertex shader breathes/deforms the cube. D3D9.PixelShader ps_3_0 Pixel shader paints an animated procedural color. D3D10.VertexShader vs_4_0 Vertex shader twists the cube. D3D10.PixelShader ps_4_0 Pixel shader procedural color. D3D10.GeometryShader gs_4_0 Geometry shader explodes triangles along face normals. D3D11.VertexShader vs_5_0 Vertex shader twist. D3D11.PixelShader ps_5_0 Pixel shader procedural color. D3D11.GeometryShader gs_5_0 Geometry shader exploding cube. D3D11.ComputeSh"}, {"t": "Shader Model 6 samples (mesh / amplification / ray tracing)", "p": "Sample reference", "u": "reference.html#shader-model-6-samples-mesh-amplification-ray-tracing", "x": "# D3D12.MeshShader , D3D12.AmplificationShader , and D3D12.RayTracing use Shader Model 6.3/6.5 , which the legacy D3DCompile / fxc path cannot target. They compile their HLSL at runtime with DXC by loading dxcompiler.dll (and dxil.dll for signing) — the app searches the Windows SDK bin\\<ver>\\x64 folders, so no extra setup is needed on a machine with the SDK installed. Amplification shaders only exist to feed a mesh shader, so that sample combines AS + MS ; ray tracing's raygen, miss, and closest-hit stages are all part of one pipeline, so it is a single combined sample. These three need a mesh-shader / DXR-capable GPU (or a recent WARP) at runtime and show a clean \"init failed\" dialog otherwise; they still build everywhere."}, {"t": "GUI sample (Nuklear)", "p": "Sample reference", "u": "reference.html#gui-sample-nuklear", "x": "# D3D12.Nuklear shows an immediate-mode GUI rendered on a Direct3D 12 backend using Nuklear (public-domain, single-header). It renders Nuklear's full widget overview — buttons, sliders, checkboxes, radio buttons, combo boxes, a color picker, tree/tab views, charts, text edit, property widgets, groups, and popups — plus a small control window. Vendored from the Nuklear repo into third_party/nuklear/ : nuklear.h , the D3D12 backend nuklear_d3d12.h with its precompiled shader headers ( nuklear_d3d12_{vertex,pixel}_shader.h ). The overview.c widget demo lives in the sample folder. The backend uses C-style COM ( COBJMACROS ), so this sample is written in C ( main.c ) and build-all.ps1 compiles it as C ( /Tc ). It links d3d12.lib , dxgi.lib , and dxguid.lib via #pragma comment , and requires Windows SDK >= 10.0.22000.0 (a lower version has a known bug that crashes the backend). Build it like any other sample: .\\build-all.ps1 -Only D3D12.Nuklear ."}, {"t": "Learning D3D12 (annotated samples with a Nuklear UI)", "p": "Sample reference", "u": "reference.html#learning-d3d12-annotated-samples-with-a-nuklear-ui", "x": "# A growing set of teaching samples, each a single self-contained main.c built on the shared Nuklear GUI backend ( third_party/nuklear/ ). Each renders a rotating cube plus a Nuklear panel that both explains and shows the live state of the D3D12 feature it focuses on, with interactive controls. They are written in C (the Nuklear backend requires C-style COM) and compute matrices with a tiny local row-vector helper (DirectXMath is C++-only). Complex samples log errors to a Cube<Sample>.log file (written next to the working directory) instead of popping message-box dialogs, so failures are easy to read after the fact. Directory layout. All D3D12 samples now live under RotatingCubes\\D3D12\\ , grouped entirely by tier in D3D12\\Tier1\\ .. D3D12\\Tier9\\ — Tier9 being the Agility-SDK / preview \"frontier\" tier — including the base cube, the shader-showcase samples, the Shader Model 6 samples, and the Nuklear GUI sample (each is placed in the tier that matches its learning level): Flow build-all.ps1 discovers samples at any depth, so -Only <FolderName> still works regardless of nesting (e.g. -Only D3D12.Textures ). The shader-showcase, Shader Model 6, and Nuklear samples are described in their"}, {"t": "Building", "p": "Sample reference", "u": "reference.html#building", "x": "# Option A — build everything (recommended): PowerShell Copy build-all.ps1 imports the VC x64 environment and invokes cl.exe directly. It writes each sample's Cube<Version>.exe and all intermediates into a per-sample Out\\ subfolder (e.g. D3D11\\D3D11.Basic\\Out\\CubeD3D11.Basic.exe , or a nested D3D12\\Tier1\\D3D12.Textures\\Out\\CubeD3D12.Textures.exe ), which is .gitignore d so build products never clutter the tree. Samples are auto-discovered at any depth, so -Only <FolderName> works no matter how a sample is nested. Option B — per project: Batch Copy build.bat locates Visual Studio with vswhere , calls vcvars64.bat , then cl . The output is Cube<Version>.exe in that folder. Tip: %ProgramFiles(x86)% contains parentheses that break for /f (...) parsing, so build.bat copies it to a temp variable first. If you ever see a build compiling unrelated files, another process on the machine is hooking cl.exe ; build-all.ps1 avoids that by calling cl.exe by full path."}, {"t": "Runtime notes", "p": "Sample reference", "u": "reference.html#runtime-notes", "x": "# D3D7 / D3D8 need the legacy Direct3D runtimes, which modern Windows ships only as 32-bit DLLs ( SysWOW64\\d3dim700.dll , SysWOW64\\d3d8.dll ). The default x64 build therefore shows a clean \"init failed\" dialog; build an x86 copy ( vcvars32.bat , then cl /EHsc /I. main.cpp user32.lib ) and it runs. tools\\capture-screenshots.ps1 does this automatically (into Out\\x86\\ ). D3D10–D3D12 run on the WARP software rasterizer if no GPU driver is available, but need a desktop session (they won't render over a headless service)."}, {"t": "D3D8 vendored headers", "p": "Sample reference", "u": "reference.html#d3d8-vendored-headers", "x": "# D3D8.Basic/d3d8.h , d3d8types.h , and d3d8caps.h are the MinGW/Wine reimplementation (LGPL, © Jason Edmeades / the Wine project), included because the modern Windows SDK no longer ships D3D8 headers. main.cpp adds two small MSVC compat shims ( __MSABI_LONG , WINBOOL ) and resolves Direct3DCreate8 at runtime via LoadLibrary(\"d3d8.dll\") , so no D3D8 import library is needed."}, {"t": "D3D7.Basic", "p": "Sample", "u": "sample-D3D7.Basic.html", "x": "The 1999 baseline: DirectDraw 7 surfaces + a D3D7 device, steered entirely by render states and transforms. Windowed via a DirectDraw clipper and a manual back-buffer blit.", "k": "sample"}, {"t": "D3D8.Basic", "p": "Sample", "u": "sample-D3D8.Basic.html", "x": "DirectDraw is gone: one IDirect3D8 device, present parameters, vertex/index buffers. Uses vendored Wine headers because the modern SDK no longer ships d3d8.h.", "k": "sample"}, {"t": "D3D9.Basic", "p": "Sample", "u": "sample-D3D9.Basic.html", "x": "The IDirect3D9 fixed-function cube - the baseline the D3D9 shader samples build on.", "k": "sample"}, {"t": "D3D9.PixelShader", "p": "Sample", "u": "sample-D3D9.PixelShader.html", "x": "Pixel shader paints an animated procedural color.", "k": "sample"}, {"t": "D3D9.VertexShader", "p": "Sample", "u": "sample-D3D9.VertexShader.html", "x": "Vertex shader breathes/deforms the cube.", "k": "sample"}, {"t": "D3D10.Basic", "p": "Sample", "u": "sample-D3D10.Basic.html", "x": "The great redesign: device + DXGI swap chain, render-target views, constant buffers and HLSL compiled at runtime with D3DCompile. No fixed function left.", "k": "sample"}, {"t": "D3D10.GeometryShader", "p": "Sample", "u": "sample-D3D10.GeometryShader.html", "x": "Geometry shader explodes triangles along face normals.", "k": "sample"}, {"t": "D3D10.PixelShader", "p": "Sample", "u": "sample-D3D10.PixelShader.html", "x": "Pixel shader procedural color.", "k": "sample"}, {"t": "D3D10.VertexShader", "p": "Sample", "u": "sample-D3D10.VertexShader.html", "x": "Vertex shader twists the cube.", "k": "sample"}, {"t": "D3D11.Basic", "p": "Sample", "u": "sample-D3D11.Basic.html", "x": "Device and immediate context split apart, feature levels, and the same HLSL pipeline as D3D10.", "k": "sample"}, {"t": "D3D11.ComputeShader", "p": "Sample", "u": "sample-D3D11.ComputeShader.html", "x": "Compute shader writes an animated texture (UAV) the cube then samples.", "k": "sample"}, {"t": "D3D11.GeometryShader", "p": "Sample", "u": "sample-D3D11.GeometryShader.html", "x": "Geometry shader exploding cube.", "k": "sample"}, {"t": "D3D11.PixelShader", "p": "Sample", "u": "sample-D3D11.PixelShader.html", "x": "Pixel shader procedural color.", "k": "sample"}, {"t": "D3D11.Tessellation", "p": "Sample", "u": "sample-D3D11.Tessellation.html", "x": "Hull/domain shaders subdivide the cube and bulge it toward a sphere (wireframe).", "k": "sample"}, {"t": "D3D11.VertexShader", "p": "Sample", "u": "sample-D3D11.VertexShader.html", "x": "Vertex shader twist.", "k": "sample"}, {"t": "D3D12.Basic", "p": "Sample", "u": "sample-D3D12.Basic.html", "x": "The minimal explicit cube: command queue, allocator, list, fence, PSO and a root signature with MVP passed as 32-bit root constants.", "k": "sample"}, {"t": "D3D12.ConstantBuffers", "p": "Sample", "u": "sample-D3D12.ConstantBuffers.html", "x": "An UPLOAD constant buffer bound via a CBV descriptor table (vs. root constants), 256-byte CBV alignment, and per-frame CB regions to avoid overwriting data the GPU is still reading.", "k": "sample"}, {"t": "D3D12.Fundamentals", "p": "Sample", "u": "sample-D3D12.Fundamentals.html", "x": "The core objects: device, command queue/allocator/list, swap chain, RTV/DSV descriptor heaps, resource barriers, the fence sync model, root signature, and PSO. Live panel shows the fence value (CPU vs GPU-completed), back-buffer index, and barrier count each frame. Controls: pause, speed, wireframe (second PSO), vsync, clear color.", "k": "sample"}, {"t": "D3D12.Nuklear", "p": "Sample", "u": "sample-D3D12.Nuklear.html", "x": "An immediate-mode GUI (Nuklear) rendered on a Direct3D 12 backend - the full widget overview that every annotated D3D12 sample builds its live panel on.", "k": "sample"}, {"t": "D3D12.PixelShader", "p": "Sample", "u": "sample-D3D12.PixelShader.html", "x": "Pixel shader procedural color.", "k": "sample"}, {"t": "D3D12.RootSignatures", "p": "Sample", "u": "sample-D3D12.RootSignatures.html", "x": "The three root-parameter kinds side by side — root constants, root descriptors (CBV), and descriptor tables — plus how root-signature layout affects binding cost.", "k": "sample"}, {"t": "D3D12.Textures", "p": "Sample", "u": "sample-D3D12.Textures.html", "x": "The full texture-upload path: a DEFAULT-heap texture staged from an UPLOAD buffer via GetCopyableFootprints + CopyTextureRegion, the COPY_DEST -> PIXEL_SHADER_RESOURCE barrier, an SRV in a shader-visible heap bound through a root descriptor table, and static point (s0) / linear (s1) samplers.", "k": "sample"}, {"t": "D3D12.TripleBuffering", "p": "Sample", "u": "sample-D3D12.TripleBuffering.html", "x": "Multiple frames in flight: N back buffers + per-frame command allocators + a fence value per frame, so the CPU stops blocking on every Present and instead only waits when it laps the GPU.", "k": "sample"}, {"t": "D3D12.VertexShader", "p": "Sample", "u": "sample-D3D12.VertexShader.html", "x": "Vertex shader twist (root constants).", "k": "sample"}, {"t": "D3D12.CopyQueue", "p": "Sample", "u": "sample-D3D12.CopyQueue.html", "x": "A dedicated COPY queue uploading data in parallel with rendering, with a cross-queue fence so the graphics queue waits for the copy to finish.", "k": "sample"}, {"t": "D3D12.GeometryShader", "p": "Sample", "u": "sample-D3D12.GeometryShader.html", "x": "Geometry shader exploding cube.", "k": "sample"}, {"t": "D3D12.IndirectDraw", "p": "Sample", "u": "sample-D3D12.IndirectDraw.html", "x": "ExecuteIndirect with a command signature: draw arguments sourced from a GPU buffer so the GPU drives draw counts/parameters without CPU round-trips.", "k": "sample"}, {"t": "D3D12.PlacedResources", "p": "Sample", "u": "sample-D3D12.PlacedResources.html", "x": "Explicit heaps + CreatePlacedResource: sub-allocating several resources from one heap, resource-heap tiers, and aliasing considerations.", "k": "sample"}, {"t": "D3D12.Tessellation", "p": "Sample", "u": "sample-D3D12.Tessellation.html", "x": "Tessellation PSO subdivides + bulges the cube (wireframe).", "k": "sample"}, {"t": "D3D12.Bindless", "p": "Sample", "u": "sample-D3D12.Bindless.html", "x": "SM5.1 dynamic indexing: an unbounded descriptor-table range (Texture2D g_tex[]) with a per-draw root-constant index selecting one of many textures — no re-binding between draws.", "k": "sample"}, {"t": "D3D12.ComputeAsync", "p": "Sample", "u": "sample-D3D12.ComputeAsync.html", "x": "An async COMPUTE queue running a compute shader (RWStructuredBuffer via a root UAV) that animates the cube vertices; the graphics queue Wait()s on the compute fence before drawing.", "k": "sample"}, {"t": "D3D12.ComputeShader", "p": "Sample", "u": "sample-D3D12.ComputeShader.html", "x": "Compute PSO writes a UAV texture, graphics PSO samples it via a descriptor table.", "k": "sample"}, {"t": "D3D12.DeferredMRT", "p": "Sample", "u": "sample-D3D12.DeferredMRT.html", "x": "A G-buffer with Multiple Render Targets (albedo + normal in one pass), then a fullscreen-triangle lighting pass that samples them. Combo view of lit/albedo/normal.", "k": "sample"}, {"t": "D3D12.AmplificationShader", "p": "Sample", "u": "sample-D3D12.AmplificationShader.html", "x": "Amplification shader turns one dispatch into a ring of orbiting cubes, each emitted by a mesh group.", "k": "sample"}, {"t": "D3D12.MSAA", "p": "Sample", "u": "sample-D3D12.MSAA.html", "x": "A multisampled render target (2x/4x/8x, capability-gated via CheckFeatureSupport) resolved into the back buffer with ResolveSubresource. Live sample-count selector.", "k": "sample"}, {"t": "D3D12.MeshShader", "p": "Sample", "u": "sample-D3D12.MeshShader.html", "x": "Mesh shader generates the whole cube on the GPU — no vertex/index buffers or input assembler.", "k": "sample"}, {"t": "D3D12.RayTracing", "p": "Sample", "u": "sample-D3D12.RayTracing.html", "x": "Full DXR pipeline: a BLAS/TLAS cube ray-traced per pixel; the TLAS instance is rotated each frame.", "k": "sample"}, {"t": "D3D12.ShadowMap", "p": "Sample", "u": "sample-D3D12.ShadowMap.html", "x": "Two-pass shadow mapping: render depth from the light's POV into an R32_TYPELESS shadow map (D32 DSV + R32 SRV), then sample it with a SamplerComparisonState / SampleCmpLevelZero. Depth-bias slider.", "k": "sample"}, {"t": "D3D12.VariableRateShading", "p": "Sample", "u": "sample-D3D12.VariableRateShading.html", "x": "Per-draw VRS (RSSetShadingRate on ID3D12GraphicsCommandList5), capability-gated on D3D12_FEATURE_D3D12_OPTIONS6. A fine procedural pattern makes coarse rates (2x2, 4x4) visibly blocky.", "k": "sample"}, {"t": "D3D12.Bundles", "p": "Sample", "u": "sample-D3D12.Bundles.html", "x": "A D3D12_COMMAND_LIST_TYPE_BUNDLE recorded once at init and replayed each frame with ExecuteBundle; the direct list sets the inherited root signature + root constants. Toggle between bundle replay and inline re-recording.", "k": "sample"}, {"t": "D3D12.MultiThreadedRecording", "p": "Sample", "u": "sample-D3D12.MultiThreadedRecording.html", "x": "Parallel command-list recording: each worker thread records a slice of a cube grid into its own allocator + list, coordinated with Win32 events, then all lists are submitted in order with one ExecuteCommandLists. The concrete payoff of the queue/allocator/list split.", "k": "sample"}, {"t": "D3D12.Predication", "p": "Sample", "u": "sample-D3D12.Predication.html", "x": "Occlusion-query-driven predication: a BINARY_OCCLUSION query resolves into a predicate buffer, and SetPredication(..., EQUAL_ZERO) makes the GPU skip the expensive draw when fully occluded — no CPU round-trip.", "k": "sample"}, {"t": "D3D12.Queries", "p": "Sample", "u": "sample-D3D12.Queries.html", "x": "Timestamp queries (GPU pass duration via GetTimestampFrequency) and pipeline-statistics queries (IA vertices, VS/PS invocations) resolved to a readback buffer and shown live.", "k": "sample"}, {"t": "D3D12.Blending", "p": "Sample", "u": "sample-D3D12.Blending.html", "x": "Alpha vs. additive blend PSOs, back-to-front sorting (toggle to see sorting artifacts), and depth-write off for transparents. Shows why transparency order matters.", "k": "sample"}, {"t": "D3D12.Instancing", "p": "Sample", "u": "sample-D3D12.Instancing.html", "x": "DrawIndexedInstanced with a per-instance vertex slot (PER_INSTANCE_DATA, offset + tint), rendering a whole grid of cubes in a single draw call. Instance-count slider.", "k": "sample"}, {"t": "D3D12.Stencil", "p": "Sample", "u": "sample-D3D12.Stencil.html", "x": "A two-pass stencil mask (D24_UNORM_S8_UINT): pass 1 writes stencil in a mask shape, pass 2 draws the cube only where StencilFunc == EQUAL — the mirror/portal/decal building block.", "k": "sample"}, {"t": "D3D12.HDR", "p": "Sample", "u": "sample-D3D12.HDR.html", "x": "An HDR10 swap chain (R10G10B10A2 + ST2084 color space via IDXGISwapChain3::SetColorSpace1), CheckColorSpaceSupport negotiation, IDXGIOutput6 luminance query, and a paper-white/brightness control. Graceful SDR fallback.", "k": "sample"}, {"t": "D3D12.MultiAdapter", "p": "Sample", "u": "sample-D3D12.MultiAdapter.html", "x": "Explicit adapter enumeration (IDXGIFactory6::EnumAdapterByGpuPreference with fallback), listing each adapter's VRAM/vendor/flags, and selecting the high-performance GPU to render on. Explains cross-adapter shared resources.", "k": "sample"}, {"t": "D3D12.Debugging", "p": "Sample", "u": "sample-D3D12.Debugging.html", "x": "The validation tooling that replaces the driver's safety net: debug layer, GPU-based validation, DRED, live ID3D12InfoQueue message drain, PIX markers (encoded by hand, no pix3.h), and a button that deliberately triggers a benign validation warning. A DirectX Dump Files (preview) panel explains console-style GPU crash dumps and probes D3D12_FEATURE_DUMP_FILE / ID3D12DevicePreview, reporting \"not available\" on the retail runtime (the API ships in Agility SDK 1.721-preview but isn't usable yet).", "k": "sample"}, {"t": "D3D12.PipelineLibraries", "p": "Sample", "u": "sample-D3D12.PipelineLibraries.html", "x": "Caching compiled PSOs to disk with ID3D12PipelineLibrary (Load/Store + Serialize to a .cache file); logs cold-create vs cached-load timing so you can see the first-run-compiles-then-caches behavior.", "k": "sample"}, {"t": "D3D12.ReservedResources", "p": "Sample", "u": "sample-D3D12.ReservedResources.html", "x": "Reserved (tiled/sparse) textures: CreateReservedResource + UpdateTileMappings binding virtual tiles to a small heap, capability-gated on TiledResourcesTier with a committed-resource fallback.", "k": "sample"}, {"t": "D3D12.DirectStorage", "p": "Sample", "u": "sample-D3D12.DirectStorage.html", "x": "Fast asset streaming (2022): IDStorageFactory → queue → request → submit → fence, loading bytes straight from disk into a D3D12 resource. Uses the out-of-band Microsoft.Direct3D.DirectStorage NuGet SDK (vendored locally, git-ignored).", "k": "sample"}, {"t": "D3D12.DynamicResources", "p": "Sample", "u": "sample-D3D12.DynamicResources.html", "x": "Shader Model 6.6 dynamic resources / bindless: HEAP_DIRECTLY_INDEXED root flags let HLSL index ResourceDescriptorHeap[] / SamplerDescriptorHeap[] directly with no descriptor tables in the root signature. Gated on shader model + resource-binding tier.", "k": "sample"}, {"t": "D3D12.EnhancedBarriers", "p": "Sample", "u": "sample-D3D12.EnhancedBarriers.html", "x": "The modern barrier model: ID3D12GraphicsCommandList7::Barrier with D3D12_TEXTURE_BARRIER groups splitting SYNC / ACCESS / LAYOUT for precise, less over-synchronizing transitions. Gated on EnhancedBarriersSupported, with a legacy ResourceBarrier fallback.", "k": "sample"}, {"t": "D3D12.LinearAlgebra", "p": "Sample", "u": "sample-D3D12.LinearAlgebra.html", "x": "SM6.10 preview. GPU-accelerated matrix math for neural rendering (#include <dx/linalg.h>, cs_6_10): a thread-scope F16 matrix × SM6.9 long-vector Multiply (inference) plus VectorAccumulate (InterlockedAccumulate), which sums 256 threads' gradients atomically (training). Both results are checked against the CPU and charted on the cube's faces. Gated on D3D12_FEATURE_LINEAR_ALGEBRA_SUPPORT. Needs the preview Agility SDK (1.721.2-preview) + preview DXC + Developer Mode, all vendored by fetch-deps.ps1. Runs on hardware when the driver exposes LinAlg, otherwise on the vendored preview WARP (--hw / --warp override).", "k": "sample"}, {"t": "D3D12.PartialPrograms", "p": "Sample", "u": "sample-D3D12.PartialPrograms.html", "x": "1.721 preview. Partial graphics programs: one VS and one PS compiled once as pre-rasterization and pixel-shader partials in a state-object collection, then late-linked (blend / rasterizer / depth) into five generic programs with AddToStateObject. It draws opaque, additive and alpha cubes with SetProgram; P swaps in equivalent classic PSOs, and the title compares compile, link and first-draw times. The basis for Advanced Shader Delivery. Needs D3D12StateObjectsExperiment; falls back to preview WARP, then to a classic PSO.", "k": "sample"}, {"t": "D3D12.RayTracing12", "p": "Sample", "u": "sample-D3D12.RayTracing12.html", "x": "DXR 1.2 / Shader Model 6.9. Opacity micromaps cut a different hole into each cube face: 12 OC1 4-state OMMs in an OMM array built with BuildRaytracingAccelerationStructure, linked to the BLAS triangles, pipeline flag ALLOW_OPACITY_MICROMAPS. O cycles OMM 2-state (0 any-hit calls) / OMM 4-state (~4K) / any-hit alpha test (~162K) / opaque. Shader Execution Reordering: dx::HitObject::TraceRay → dx::MaybeReorderThread(hit, faceHint, 3) → HitObject::Invoke, toggled with S, with the OPTIONS22.ShaderExecutionReorderingActuallyReorders cap and GPU timestamps in the title. Hardware → preview WARP → DXR 1.0 fallback.", "k": "sample"}, {"t": "D3D12.SamplerFeedback", "p": "Sample", "u": "sample-D3D12.SamplerFeedback.html", "x": "DirectX 12 Ultimate Sampler Feedback: a paired feedback map (CreateSamplerFeedbackUnorderedAccessView, DXGI_FORMAT_SAMPLER_FEEDBACK_) records which* texture mips a shader actually sampled (via WriteSamplerFeedback in SM6.5) — the basis for texture streaming and texture-space shading. Gated on SamplerFeedbackTier.", "k": "sample"}, {"t": "D3D12.WorkGraphs", "p": "Sample", "u": "sample-D3D12.WorkGraphs.html", "x": "GPU-driven Work Graphs (2024): an executable state object of shader nodes launched with DispatchGraph (ID3D12GraphicsCommandList10) so the GPU spawns its own follow-on work. Gated on WorkGraphsTier.", "k": "sample"}]};